(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c65"]=[{"id":"00006394","register_sub_id":"101","register_pk":"107377","name":"山本家住宅隠居所","kana":"やまもとけじゅうたくいんきょじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県海南市阪井679他","lat":34.160172,"lng":135.259781,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積128㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"30 － 0126","desc":"内蔵二の北、小路を挟んだ別敷地に建つ。桁行５間、梁行４間半の木造平屋建で、入母屋造桟瓦葺。南正面に切妻屋根の玄関がつく。瓦葺庇を巡らし、正面は出桁造とする。矩折れの中廊下をもち、座敷８畳など４室を配す。外壁の小壁や妻壁の赤土塗が鮮やかである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006394"},{"id":"00006390","register_sub_id":"101","register_pk":"107373","name":"山本家住宅内蔵一","kana":"やまもとけじゅうたくうちぐらいち","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県海南市阪井679他","lat":34.16008311,"lng":135.25979857,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"30 － 0124","desc":"店蔵一の北西に建つ土蔵造２階建である。桁行３間半、梁間２間の南北棟で、切妻造本瓦葺。花崗岩の高い石垣積基礎の上に建ち、外壁は白漆喰塗で、腰を竪羽目板張とする。東面南寄りに戸口を設け、小庇をつける。小屋組は登梁。西方からの景観の要となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006390"},{"id":"00006391","register_sub_id":"101","register_pk":"107374","name":"山本家住宅内蔵二","kana":"やまもとけじゅうたくうちぐらに","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県海南市阪井679他","lat":34.16006962,"lng":135.259842,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"30 － 0125","desc":"内蔵一の東に棟方向を違えて建つ土蔵造２階建である。桁行３間半、梁間２間の東西棟で、切妻造桟瓦葺とし、南に鉄板葺庇をつけて戸口を開く。基礎は花崗岩の高い石垣である。外壁は白漆喰塗で、腰を竪羽目板張、妻に母屋形を見せる。小屋組は登梁。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006391"},{"id":"00006385","register_sub_id":"101","register_pk":"107368","name":"山本家住宅主屋","kana":"やまもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県海南市阪井679他","lat":34.15994265,"lng":135.26002368,"geo_status":"db","era":"江戸末期／明治39増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部3階建、瓦葺、建築面積177㎡","structure_material":"木造平屋一部3階建","registered":"2007.10.02(平成19.10.02)","register_no":"30 － 0123","desc":"事務所の東に国道からやや退いて建つ。木造つし２階建、切妻造平入の居室部の東に、寄棟造の３階をのせた座敷部を増築。居室部は下屋庇とも本瓦葺、座敷部は桟瓦葺。外壁は黒漆喰塗の真壁造である。３階座敷には高欄付の縁をつける。屋根構成に変化を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006385"},{"id":"00006392","register_sub_id":"101","register_pk":"107375","name":"山本家住宅門","kana":"やまもとけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県海南市阪井679他","lat":34.15987284,"lng":135.26003114,"geo_status":"db","era":"明治39頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造、瓦葺、間口1.2m、塀延長3.6m付","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"30 － 0128","desc":"主屋の正面東寄りにあり、居室部表から座敷部の庭園に入る門で、西面する。間口４尺の腕木門である。切妻屋根は和歌山特有の丸桟瓦で葺く。軒は疎垂木で軽快。１枚板の門扉の両開とする。袖塀は黒漆喰塗で、腰を竪板張とし、丸桟瓦葺。屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006392"},{"id":"00012792","register_sub_id":"101","register_pk":"367695","name":"遊心庵（旧田中家住宅）主屋","kana":"ゆうしんあん（きゅうたなかけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県日高郡美浜町大字三尾837","lat":33.89364139,"lng":135.13334167,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積205㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"30 － 0258","desc":"町西部の旧三尾村中心部の高台に南面して建つ。入母屋造桟瓦葺の平家建で、正面東端に入母屋造の角屋を出し、西側に寄棟造の別棟を付す。東に土間、西の前後に各3室を配し、前列上手に座敷、別棟に洋室を設ける。カナダ移民が故郷に建てた上質な和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012792"},{"id":"00012793","register_sub_id":"101","register_pk":"367696","name":"遊心庵（旧田中家住宅）門及び塀","kana":"ゆうしんあん（きゅうたなかけじゅうたく）もんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県日高郡美浜町大字三尾837","lat":33.89364139,"lng":135.13334167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 コンクリート造、間口2.4m 塀 コンクリート造、総延長20m","structure_material":"門 コンクリート造","registered":"2019.03.29(平成31.03.29)","register_no":"30 － 0259","desc":"敷地南面の石垣上の東寄りに開く門と左右に延びる塀。コンクリート造のモルタル洗出し仕上。門は角形の門柱を間口二・四メートルで立て、塀は壁面に柱形を表し、門塀とも頂部に見切二段をあしらい表情をつける。伝統的な屋敷構えに近代的な彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012793"},{"id":"00006929","register_sub_id":"101","register_pk":"107911","name":"和合庵主屋","kana":"わごうあんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山字一心院谷34","lat":34.21713789,"lng":135.58737884,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積200㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"30 － 0130","desc":"桁行４間半梁間４間、南北棟、入母屋造鉄板葺、木造２階建の主体部の三方に廊下をまわし、東南隅に玄関、東面から北面にかけて応接室や内玄関、台所、仏間を平屋建で配する。入母屋の妻や応接室東面の開口の形状は特徴的で、地元高野山の大工堀野久吉の作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006929"},{"id":"00006930","register_sub_id":"101","register_pk":"107912","name":"和合庵土蔵","kana":"わごうあんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山字一心院谷34","lat":34.2172671,"lng":135.58739792,"geo_status":"db","era":"大正15頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、銅板葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"30 － 0131","desc":"敷地の北端に東西棟で建ち、主屋と渡り廊下で接続する。桁行２間半梁間２間、切妻造桟瓦型銅板葺の２階建で、南面西端近くに戸口を設ける。外壁は、白漆喰塗で腰に竪板を張り、東面の各階、西面２階に窓を開ける。窓庇の持送りに繰形をつけるなど丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006930"},{"id":"00006932","register_sub_id":"101","register_pk":"107914","name":"和合庵塀","kana":"わごうあんへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山字一心院谷34","lat":34.21701299,"lng":135.58744604,"geo_status":"db","era":"大正15頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造、銅板葺、延長7.4m","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"30 － 0133","desc":"門の脇から通り沿いに南方に延びる長７．４ｍの木造屋根塀で、割石乱積の擁壁上に建ち、内側に斜材の支えを入れ、柱と貫で繋ぐ。屋根は起りを付け、銅板で桟瓦型に葺く。壁は外側がひしゃぎ竹の竪詰打、内側が杉皮の網代組とした瀟洒な数寄屋風のつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006932"},{"id":"00006931","register_sub_id":"101","register_pk":"107913","name":"和合庵門","kana":"わごうあんもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山字一心院谷34","lat":34.217049,"lng":135.587448,"geo_status":"db","era":"大正15頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造、鉄板葺、間口1.5m","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"30 － 0132","desc":"主屋の南東端に取り付き、通りから石段を上がった踊場に北向きに建つ。門口幅１．５ｍ、東西棟、寄棟造鉄板葺の腕木門で、北面に「和合庵」の扁額を掲げる。柱や冠木に節の目立つ丸太を用い、屋根面に起りを付け、吹寄垂木を配るなど凝ったつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006931"},{"id":"00013758","register_sub_id":"101","register_pk":"505315","name":"旧楠本家住宅（和田家住宅）離座敷","kana":"わだけじゅうたく（きゅうくすもとけじゅうたく)はなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県日高郡日高町大字原谷字立花川782-4","lat":33.96746944,"lng":135.16556667,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"30 － 305","desc":"平屋建寄棟造桟瓦葺で四周に下屋を廻す。中庭に面して広縁を廻しガラス戸を建てる。内部は四室を田字形にとる。座敷は目の詰んだ栂を用い、特に四方柾の柱は目を引く。欄間など細部にも意匠を凝らした上質な接客空間。熊野古道紀伊路沿いの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013758"},{"id":"00006178","register_sub_id":"101","register_pk":"107162","name":"和田家住宅主屋","kana":"わだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市和歌浦中1-2-20","lat":34.193108,"lng":135.169891,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造2階建、瓦葺、建築面積161㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"30 － 0116","desc":"街路に接した敷地東辺に東面して建つ。起りのある南北棟の入母屋造，本瓦葺，２階建で，周囲に下屋を廻す。正面１階は出格子を連続するが，２階壁面は黒漆喰塗，額縁付の格子窓を設ける。重厚かつ風格のある外観をよく残し，伝統的な町並景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006178"},{"id":"00006245","register_sub_id":"101","register_pk":"107229","name":"和田家住宅土蔵","kana":"わだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市和歌浦中1-2-20","lat":34.193287,"lng":135.169434,"geo_status":"db","era":"明治38頃","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"30 － 0117","desc":"南北棟の切妻造，本瓦葺，平入の土蔵造２階建で，東面１階に庇付の扉口，２階南妻面に庇付の窓を設ける。小屋は地棟に登梁を架けた形式で，漆喰塗の外壁は腰を縦板で覆い，一部を鉄板で保護しているが，丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006245"},{"id":"00006246","register_sub_id":"101","register_pk":"107230","name":"和田家住宅塀","kana":"わだけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市和歌浦中1-2-20","lat":34.1933912,"lng":135.16941314,"geo_status":"db","era":"明治38頃","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土塀、瓦葺、総延長46m","structure_material":"土塀","registered":"2007.07.31(平成19.07.31)","register_no":"30 － 0118","desc":"土蔵の南側に延長１７ｍ，北側に折曲り延長２９ｍで延びる土塀。高さ約２．３ｍで，結晶片岩と瓦及び土で構築し，頂部に桟瓦を載せる。石の積み方に変化を持たせ，意匠的にも工夫が見られ，見応えのある景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006246"},{"id":"00009988","register_sub_id":"101","register_pk":"196135","name":"青木家住宅（旧本尊美家住宅）表門","kana":"あおきけじゅうたく（きゅうぽんそんびけじゅうたく）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市北区上賀茂南大路町59","lat":35.05557457,"lng":135.75522932,"geo_status":"db","era":"昭和8頃／平成22移築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、瓦葺、間口2.4m、潜戸付","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0444","desc":"主屋玄関の西正面に建ち、四脚平唐門、桟瓦葺で、北側に潜戸を吊る。本柱を円柱、控柱を面取角柱として各柱上に舟肘木を置き、棟通りでは男梁上に大斗舟肘木を重ねて棟木を受け、軒は疎垂木で木小舞を配る。主屋同様に社寺建築の意匠を引用した、優美な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009988"},{"id":"00009987","register_sub_id":"101","register_pk":"196134","name":"青木家住宅（旧本尊美家住宅）主屋","kana":"あおきけじゅうたく（きゅうぽんそんびけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市北区上賀茂南大路町59","lat":35.05555734,"lng":135.75543284,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積192㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0443","desc":"上賀茂の住宅地に西面して建つ。木造二階建、入母屋造桟瓦葺で、正面に唐破風玄関を構える。上下階とも南庭を囲むように南東面に座敷と縁を配し、玄関周りや擬宝珠付階段に社寺建築の意匠を引用する。ヒノキの良材をふんだんに使い、施工も良質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009987"},{"id":"00010184","register_sub_id":"101","register_pk":"198017","name":"青木家住宅主屋","kana":"あおきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区富小路通三条上る福長町110","lat":35.009329,"lng":135.765107,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積86㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"26 － 0459","desc":"東西に長い敷地前寄りに洋間を配し、後方に玄関を介して和室棟を建てる。洋間はステンドグラスや暖炉を備える洗練された意匠で、和室は数寄屋を基調とし、特に二階座敷の付書院欄間に違棚を設け、趣向を凝らす。近代の住宅思潮と数寄屋意匠を兼備した住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010184"},{"id":"00010185","register_sub_id":"101","register_pk":"198018","name":"青木家住宅土蔵","kana":"あおきけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区富小路通三条上る福長町110","lat":35.009329,"lng":135.765321,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積13㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"26 － 0460","desc":"主屋後方に中庭を挟んで南北棟で建つ。土蔵造二階建、桁行三・九メートル梁間三・〇メートル、切妻造桟瓦葺で、西面を戸口として鉄扉を開き、下屋を設ける。外壁は漆喰塗で鉢巻を廻らし、二階西面に窓を穿つ。数寄屋意匠の主屋と対峙し、良質な庭空間を創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010185"},{"id":"00004266","register_sub_id":"101","register_pk":"105256","name":"アサヒビール大山崎山荘美術館彩月庵（茶室）","kana":"あさひびーるおおやまざきさんそうびじゅつかんさいげつあん（ちゃしつ）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字銭原5-3","lat":34.89554746,"lng":135.67928776,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"26 － 0177","desc":"本館北西，宝積寺との境界近くに建つ茶室。切妻造，桟瓦葺で，持仏堂を兼ねた立礼席と前室及び水屋からなる。室内は石敷で，主室に２畳の床上部，床，仏壇を備える。丸太を用いた軽快で開放的な数寄屋風の造りで，簡素ながら瀟洒で見所の多い室内を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004266"},{"id":"00004267","register_sub_id":"101","register_pk":"105257","name":"アサヒビール大山崎山荘美術館橡の木茶屋","kana":"あさひびーるおおやまざきさんそうびじゅつかんとちのきちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字銭原5-3","lat":34.89525204,"lng":135.67959766,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建地階付、瓦葺、建築面積16㎡","structure_material":"木造平屋建地階付","registered":"2004.07.23(平成16.07.23)","register_no":"26 － 0178","desc":"山腹に鉄筋コンクリート造石張の地階を築き，その上に張り出して建つ。南，西面は腰掛を設け，外部壁面は丸太組でつくる。内部は寄木張の土間床とし，柱，梁は丸太で，床や下地窓を備えた数寄屋風意匠になる。和洋を巧みに折衷した構成の建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004267"},{"id":"00004265","register_sub_id":"101","register_pk":"105255","name":"アサヒビール大山崎山荘美術館本館","kana":"あさひびーるおおやまざきさんそうびじゅつかんほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字銭原5-3","lat":34.89556919,"lng":135.67964951,"geo_status":"db","era":"大正初期／昭和2増築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"鉄筋コンクリート造及び木造地上3階地下1階建、鉄板葺、建築面積372㎡","structure_material":"鉄筋コンクリート造及び木造地上3階地下1階建","registered":"2004.07.23(平成16.07.23)","register_no":"26 － 0176","desc":"実業家加賀正太郎の別邸。鉄筋コンクリート造及び木造，屋根瓦葺形鉄板葺で，急勾配の切妻屋根を戴く平屋部分とハーフティンバーの３階建部分がＴ字形平面を構成する。変化に富んだ外観と，ジャコビアン様式を基調とした充実した室内意匠をもつ質の高い建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004265"},{"id":"00002056","register_sub_id":"101","register_pk":"103046","name":"芦田家住宅（旧片岡家別荘）主屋","kana":"あしだけじゅうたく（きゅうかたおかけべっそう）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府福知山市下柳18","lat":35.3030169,"lng":135.12617017,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造地上2階地下1階建、瓦葺、建築面積123㎡","structure_material":"木造地上2階地下1階建","registered":"2000.12.04(平成12.12.04)","register_no":"26 － 0079","desc":"近代福知山の基盤を築いた実業家の別業で，由良川左岸の堤防道路に沿った敷地に建つ。堤防の高低差を巧みに利用した三層建物で，中層階を生活空間に充て，上層階に奇想に富んだ床構えをもつ座敷を配置する。赤松の上材をふんだんに用いた近代別荘建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002056"},{"id":"00010188","register_sub_id":"101","register_pk":"198021","name":"新居家住宅主屋","kana":"あらいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市伏見区淀新町99-1他","lat":34.901738,"lng":135.719574,"geo_status":"db","era":"大正15／昭和前期改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積187㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"26 － 0463","desc":"西面する玄関の北隣に洋間、南側に和室を配し、南東に離れを張出す。洋間は切妻屋根にスパニッシュ瓦を葺き、妻飾りや内装を洗練した幾何意匠でまとめる。和室は数寄屋風の座敷飾や根来塗框の建具など、創意に満ちた意匠になる。戦前の洋間付郊外住宅の佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010188"},{"id":"00006546","register_sub_id":"101","register_pk":"107529","name":"荒木家住宅（旧林家住宅）主屋","kana":"あらきけじゅうたく（きゅうはやしけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫竹西南町17-1","lat":35.045792,"lng":135.746719,"geo_status":"db","era":"文化4","year":1807,"year_source":"db","year_min":1807,"year_max":1807,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積143㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0254","desc":"大徳寺北の今宮通の北に敷地を構える。街路に面して前庭をとり，南面して建つ間口５間半，奥行６間半の平屋建である。屋根は切妻造，桟瓦葺で，土間上に越屋根を設け，表に瓦葺庇がつく。内部は東側が通り土間，西側は居室で，表庭に面して８畳座敷を配す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006546"},{"id":"00006547","register_sub_id":"101","register_pk":"107530","name":"荒木家住宅（旧林家住宅）土蔵","kana":"あらきけじゅうたく（きゅうはやしけじゅうたく）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫竹西南町17-1","lat":35.04594,"lng":135.746674,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0255","desc":"主屋の背面，敷地西寄りに建つ土蔵造２階建。桁行１間半，梁間２間規模の東西棟で，切妻造の置屋根を桟瓦葺とする。小屋組は梁を用いず，柱が母屋と棟木を受ける。南面戸口には瓦葺庇を架ける。外壁は白漆喰塗で２階南面に窓を開く。小規模ながら端正な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006547"},{"id":"00003889","register_sub_id":"101","register_pk":"104879","name":"安藤家住宅（旧藤井繁次郎邸）","kana":"あんどうけじゅうたく（きゅうふじいしげじろうてい）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区鹿ケ谷桜谷町126","lat":35.019444,"lng":135.796051,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積342㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"26 － 0161","desc":"ハーフティンバー・スタイルを基調とする英国風住宅で，一部に古典様式の列柱等の独自色を見せる。内部は一部に客船の建具等を使用し，寄木張の床，プラスターによる壁面装飾など，船舶を意識した豪華な内装を誇る。設計・施工は，ともに鴻池組による。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003889"},{"id":"00015324","register_sub_id":"101","register_pk":"532448","name":"井口家住宅表門及び塀","kana":"いぐちけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市左京区岡崎円勝寺町91-47","lat":35.01068889,"lng":135.78405556,"geo_status":"db","era":"大正15年頃／昭和中期・同後期改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"表門 鉄筋コンクリート造、間口2.2m 塀 鉄筋コンクリート造、総延長61m","structure_material":"表門 鉄筋コンクリート造","registered":"2025.03.13(令和7.03.13)","register_no":"26 - 0685","desc":"通りに北面する表門と敷地周囲を画す塀で鉄筋コンクリート造モルタル洗出仕上。表門は庇を水平に載せ軽快にみせる。塀は高さ３メートル、隣地境の西面は高さ5・5メートルとし、控壁を付す。洗練されたつくりの門と塀で大正末期の開発住宅地の景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015324"},{"id":"00015323","register_sub_id":"101","register_pk":"532447","name":"井口家住宅主屋","kana":"いぐちけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市左京区岡崎円勝寺町91-47","lat":35.01085278,"lng":135.78409167,"geo_status":"db","era":"大正15年／平成16年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積123㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"26 - 0684","desc":"岡崎の遊園地跡の開発地に建つ洋風住宅の主屋。通りより控えて建つ２階建寄棟造桟瓦葺で、北西隅に切妻屋根、北・東・南面にドーマー窓を付し、外壁モルタル塗仕上。内部はＬ字の中廊下形式で二階に数寄屋風座敷を配す。大正末期の開発地で目を惹く洋風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015323"},{"id":"00014185","register_sub_id":"101","register_pk":"508815","name":"石﨑家住宅主屋","kana":"いしざきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市上京区石薬師通寺町東入新夷町391","lat":35.02686944,"lng":135.76865833,"geo_status":"db","era":"大正15年／昭和54年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"26-0644","desc":"京都御所の東の住宅地に建つ藤井厚二設計の独立住宅。玄関北の階段前をホールとし、居間を中心に置く間取りが試みられた。応接室や居間は洋室に地袋棚を設けて創意を示す。二階は階段室の周りに客間六畳、書斎や寝室を配す。簡潔な設えの都市住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014185"},{"id":"00009511","register_sub_id":"101","register_pk":"194304","name":"石田家住宅主屋","kana":"いしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府長岡京市井ノ内北内畑26","lat":34.94346041,"lng":135.68832893,"geo_status":"db","era":"江戸中期／江戸後期増築・平成23年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺一部瓦葺、建築面積178㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"26 － 0415","desc":"敷地北寄りに南面し、木造平屋建、入母屋造妻入茅葺型銅板葺で、桟瓦葺の下屋を廻らし、西側に入母屋造の角屋を付ける。東に土間、西に二列の居室を配して式台を構え、角屋はトコ・棚を備える主座敷とする。摂丹型民家を基本に発展した形態をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009511"},{"id":"00009512","register_sub_id":"101","register_pk":"194305","name":"石田家住宅土蔵","kana":"いしだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府長岡京市井ノ内北内畑26","lat":34.94351276,"lng":135.68818557,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"26 － 0416","desc":"主屋北西側に、通りに面して南北棟で建つ。土蔵造二階建、桁行五・九メートル梁間三・九メートル、切妻造桟瓦葺で、東面の戸口に下屋を設ける。外壁は漆喰塗で腰を竪板張とし、南面と西面に穿たれた小窓に瓦葺の小庇を付ける。旧家の屋敷構えに風格を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009512"},{"id":"00009513","register_sub_id":"101","register_pk":"194306","name":"石田家住宅土塀","kana":"いしだけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府長岡京市井ノ内北内畑26","lat":34.94361295,"lng":135.68830217,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土塀、瓦葺、総延長91m","structure_material":"土塀","registered":"2013.03.29(平成25.03.29)","register_no":"26 － 0417","desc":"敷地南西隅から北西隅を経て北東隅までを囲繞する土塀。高さ二メートル内外、総延長九一・一メートルを測る。野面積基礎上に建ち、切妻造、本瓦葺及び桟瓦葺である。壁は漆喰塗仕上げで、一段または二段の軒蛇腹をつくる。集落内の歴史的景観を引き立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009513"},{"id":"00007230","register_sub_id":"101","register_pk":"108212","name":"伊藤喜商店無量子庵井戸","kana":"いとうきしょうてんむりょうしあんいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市東山区松原通大和大路東入二丁目轆轤町100-1","lat":34.9972888,"lng":135.77410424,"geo_status":"db","era":"大正15頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"石造、面積0.81㎡、上屋付","structure_material":"石造","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0315","desc":"無量子庵主屋の南側東寄り、土蔵の東北に位置する。井戸枠は方０．９ｍで、花崗岩の板石４枚を相欠に組み合せる。周囲にモルタル塗の洗い場を設ける。井戸屋形は銅板葺の片流屋根で、柱の根元は花崗岩製とする。動線上の支障となる、主屋側の北西隅柱を省略する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007230"},{"id":"00007227","register_sub_id":"101","register_pk":"108209","name":"伊藤喜商店無量子庵主屋","kana":"いとうきしょうてんむりょうしあんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市東山区松原通大和大路東入二丁目轆轤町100-1","lat":34.997341,"lng":135.774063,"geo_status":"db","era":"大正15頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積136㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0312","desc":"敷地の南半中央に建つ木造２階建。桁行６間半梁間４間半規模の東西棟で切妻造桟瓦葺。内部は東が玄関と土間、台所で、廊下と階段を挟み、西が十畳座敷と次の間とし、正・背面を縁とする。２階に数寄屋風の十畳座敷などを配す。良質な近代和風住宅遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007227"},{"id":"00007228","register_sub_id":"101","register_pk":"108210","name":"伊藤喜商店無量子庵茶室及び待合","kana":"いとうきしょうてんむりょうしあんちゃしつおよびまちあい","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市東山区松原通大和大路東入二丁目轆轤町100-1","lat":34.99742662,"lng":135.77398401,"geo_status":"db","era":"大正15頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"茶室 木造平屋建、瓦葺一部銅板葺 建築面積35㎡ 待合 木造平屋建、鉄板葺、建築面積3.7㎡","structure_material":"茶室 木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0313","desc":"無量子庵主屋の北に接続する木造平屋建で、茶室玄関や三畳、水屋を介して四畳半茶室に至る。屋根は切妻屋根を組み合せ、茶室には庇が付く。待合は茶室西方に位置する。桁行１０尺梁間４尺規模の南北棟で、東向きに建つ。軸部は磨丸太とし、丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007228"},{"id":"00007229","register_sub_id":"101","register_pk":"108211","name":"伊藤喜商店無量子庵土蔵","kana":"いとうきしょうてんむりょうしあんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市東山区松原通大和大路東入二丁目轆轤町100-1","lat":34.99723879,"lng":135.77407324,"geo_status":"db","era":"大正15頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0314","desc":"無量子庵主屋の南に渡廊下を介して接続する土蔵造２階建。桁行６．０ｍ梁間４．１ｍ規模の東西棟で、切妻造本瓦葺とする。北面の蔵前に戸口を開き、両開の鉄扉を吊る。外壁は漆喰仕上げで、腰に水切りをまわす。東妻の１、２階、西妻の２階に瓦庇付の窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007229"},{"id":"00016537","register_sub_id":"101","register_pk":"574899","name":"伊東家住宅一ノ蔵","kana":"いとうけじゅうたくいちのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京田辺市普賢寺公家谷106","lat":34.787085,"lng":135.76166194,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積23㎡","structure_material":"土蔵造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"26 - 0732","desc":"敷地北西隅に位置する農具などの収納蔵。東面して切石積基礎に建つ平屋建切妻造平入、置屋根形式の桟瓦葺。外壁漆喰塗で頂部は蛇腹を廻らし、腰は高く焼杉板を張る。小屋組は曲がりの強い梁を二通り架け、母屋と棟木を支持する。敷地北辺の景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016537"},{"id":"00016536","register_sub_id":"101","register_pk":"574898","name":"伊東家住宅主屋","kana":"いとうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京田辺市普賢寺公家谷106","lat":34.787085,"lng":135.76166194,"geo_status":"db","era":"大正10年／平成11年改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積176㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"26 - 0731","desc":"市街地南西の山間に位置する旧家の主屋。敷地中央に南面して建つ、平屋建入母屋造桟瓦葺で正背面に下屋を付し、南東に便所棟を附属。西は土間、東は７室を配し、南東を床構え付き座敷とする。前身主屋の古材を用いて再建し、式台など旧家の格式を備えた主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016536"},{"id":"00016539","register_sub_id":"101","register_pk":"574901","name":"伊東家住宅三ノ蔵","kana":"いとうけじゅうたくさんのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京田辺市普賢寺公家谷106","lat":34.787085,"lng":135.76166194,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"26 - 0734","desc":"敷地北辺東寄りに位置する家財蔵。南面して切石基礎に建つ２階建切妻造平入で、屋根は置屋根形式の桟瓦葺。外壁は漆喰塗で床下を透かし、腰は焼杉板張、戸口上部に腕木庇を付す。各階板敷の一室で小屋組は登梁形式。土蔵が並び建つ敷地北辺の一角を占める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016539"},{"id":"00016541","register_sub_id":"101","register_pk":"574903","name":"伊東家住宅長屋門","kana":"いとうけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京田辺市普賢寺公家谷106","lat":34.787085,"lng":135.76166194,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"26 - 0736","desc":"敷地南面西寄りに位置する長屋門。南面して建つ平屋建切妻造平入桟瓦葺。外壁は漆喰塗仕上で、正面の二箇所に横連子窓を開ける。平面は中央を門口とし、東・西に納屋を配する。前身建物の古材を用いて再建し、旧家の屋敷規模に相応しい構えを持つ長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016541"},{"id":"00016538","register_sub_id":"101","register_pk":"574900","name":"伊東家住宅二ノ蔵","kana":"いとうけじゅうたくにのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京田辺市普賢寺公家谷106","lat":34.787085,"lng":135.76166194,"geo_status":"db","era":"江戸後期／平成22年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"26 - 0733","desc":"敷地北辺西寄りに位置する旧家財蔵。南面して切石積基礎に建つ２階建切妻造平入で屋根は置屋根形式の桟瓦葺。外壁漆喰塗で床下を透かし、軒を塗込め、腰は高く焼杉板を張る。小屋組は曲がり梁を用いた折置組で古風な形式。戸口の庇も塗込め重厚な構えの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016538"},{"id":"00016540","register_sub_id":"101","register_pk":"574902","name":"伊東家住宅四ノ蔵","kana":"いとうけじゅうたくよんのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京田辺市普賢寺公家谷106","lat":34.787085,"lng":135.76166194,"geo_status":"db","era":"江戸後期／平成4年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積28㎡","structure_material":"土蔵造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"26 - 0735","desc":"敷地南東隅に位置する旧米蔵。西面して低い切石積基礎に建つ、平屋建切妻造平入桟瓦葺。外壁は漆喰塗仕上で軒に鉢巻を廻らし、腰は焼杉板を張る。内部は１室とし、小屋組は桁行中央に梁を架け、束で棟木を受ける。露地庭の南東に建ち一つの点景を与える存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016540"},{"id":"00016542","register_sub_id":"101","register_pk":"574904","name":"伊東家住宅露地門及び土塀","kana":"いとうけじゅうたくろじもんおよびどべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"京都府","address":"京都府京田辺市普賢寺公家谷106","lat":34.787085,"lng":135.76166194,"geo_status":"db","era":"昭和中期","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"露地門 木造、銅板葺、間口1.2m 土塀 瓦葺、総延長10m","structure_material":"露地門 木造","registered":"2026.02.10(令和8.02.10)","register_no":"26 - 0737","desc":"主屋の南東に広がる露地庭の西辺を画す露地門と両脇に続く土塀。西面して建つ露地門は、一間一戸、切妻造平入銅板葺で、チョウナ斫り仕上の柱、磨き丸太の桁、竹の垂木など全体に数寄屋風の意匠でまとめる。目板瓦葺の土塀とともに主屋の正面構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016542"},{"id":"00003113","register_sub_id":"101","register_pk":"104103","name":"稲葉家住宅北宝蔵","kana":"いなばけじゅうたくきたほうぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京丹後市久美浜町3102","lat":35.606083,"lng":134.897751,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積12㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"26 － 0145","desc":"主屋東側に廊下で接続する２棟の土蔵のうち北側の蔵で，南北棟で建つ。桁行２間梁間１間半規模，切妻造，桟瓦葺の２階建土蔵で，古図から主屋建設時に曳家された経緯がわかる。主屋，長屋門，南宝蔵とともに屋敷の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003113"},{"id":"00003110","register_sub_id":"101","register_pk":"104100","name":"稲葉家住宅主屋","kana":"いなばけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京丹後市久美浜町3102","lat":35.6061957,"lng":134.89755659,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造2階建、瓦葺、建築面積390㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"26 － 0142","desc":"稲葉家は江戸時代以来の豪商で，久美浜町の中央に広い敷地を構える。主屋は，地元の大工黒崎文吉が手がけた大規模な切妻造，桟瓦葺，２階建の住宅で，地域の伝統を保持しながら近代的な中廊下の平面を取り入れた新機軸を見せる。内部の吹き抜け空間も見所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003110"},{"id":"00003111","register_sub_id":"101","register_pk":"104101","name":"稲葉家住宅長屋門","kana":"いなばけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京丹後市久美浜町3102","lat":35.605988,"lng":134.897339,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積34㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"26 － 0143","desc":"敷地南側の道路に開く長屋門。通常の長屋門とは異なり２階建で２階は前方に１尺持ち出され，切妻造桟瓦葺の屋根には卯建が上げられるなど，町家の主屋のような外観に見える。道路から望見できる位置にあって豪商の家格をあらわす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003111"},{"id":"00003112","register_sub_id":"101","register_pk":"104102","name":"稲葉家住宅南宝蔵","kana":"いなばけじゅうたくみなみほうぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京丹後市久美浜町3102","lat":35.606014,"lng":134.89769,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"26 － 0144","desc":"主屋東側に廊下で接続する２棟の土蔵のうち南側の蔵で，東西棟で建つ。桁行３間梁間２間，２階建，切妻造，桟瓦葺の置屋根で，主屋と同時に建てられたと考えられる。主屋と一体となって建築群を構成し，屋敷の景観要素として評価できる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003112"},{"id":"00014630","register_sub_id":"101","register_pk":"515172","name":"今尾家住宅茶室薫風亭","kana":"いまおけじゅうたくちゃしつくんぷうてい","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府長岡京市天神二丁目45-4","lat":34.92459444,"lng":135.68733889,"geo_status":"db","era":"大正後期／平成24年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺一部鉄板葺、建築面積98㎡、渡廊下付","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"26 - 0655","desc":"長岡天満宮の八条ヶ池西岸に位置する日本画家今尾景年の茶室。二階建入母屋造桟瓦葺で全体にＬ字形平面とし、西南隅を玄関、東に広間、北に四畳半を配し周囲に廊下を巡らし庭に臨む。広間は北を床構えとし、大きな丸窓や角窓の平書院などを配した自由な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014630"},{"id":"00014631","register_sub_id":"101","register_pk":"515173","name":"今尾家住宅土蔵","kana":"いまおけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府長岡京市天神二丁目45-4","lat":34.92464722,"lng":135.68723056,"geo_status":"db","era":"昭和前期／昭和44年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積55㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"26 - 0656","desc":"茶室の北東に位置し日本画作品を収納する土蔵。二階建切妻造平入桟瓦葺で東に戸口を開けて下屋を付し、西面腰に塀を付す。各階とも一室の板敷で、北辺に階段を設ける。外観は土蔵造漆喰仕上、東と南に開ける窓に鉄扉を入れる。小規模ながら重厚な外観の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014631"},{"id":"00002946","register_sub_id":"101","register_pk":"103936","name":"今林家住宅米蔵","kana":"いまばやしけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府宮津市字万町604-1","lat":35.53601218,"lng":135.19207625,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0136","desc":"通りに面し，主屋の東側に位置する。東西棟，切妻造，桟瓦葺の妻入２階建土蔵で，通り側に主屋と高さを揃えた半間幅の下屋庇を設ける。平側をたすき状，妻側を格子状とした海鼠壁で築き，形の異なる開口部を上下に設けるなど，外観に変化を付けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002946"},{"id":"00002948","register_sub_id":"101","register_pk":"103938","name":"今林家住宅道具蔵","kana":"いまばやしけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府宮津市字万町604-1","lat":35.53632,"lng":135.19199302,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0138","desc":"敷地北端にあり，東西棟で建つ。切妻造，桟瓦葺，外装漆喰塗の平入２階建土蔵で，梁間を桁行よりも長くとり，大きな妻面を造り，その北側の上下に窓をとる。市内の土蔵に散見される，垂木を扇状に配する特異なつくりをよく残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002948"},{"id":"00002949","register_sub_id":"101","register_pk":"103939","name":"今林家住宅味噌蔵","kana":"いまばやしけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府宮津市字万町604-1","lat":35.53612739,"lng":135.1920892,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0139","desc":"敷地北東端にある東西棟，切妻造，桟瓦葺，平入の２階建土蔵。漆喰塗を基調とし，腰を竪板張とした外装で，妻面中央の上下に窓を設けるなど，全体的に簡素ながら変化のある外観を見せる。他３棟の蔵と同じく垂木を扇状に配する構造を特徴とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002949"},{"id":"00012208","register_sub_id":"101","register_pk":"353008","name":"今宮神社東門","kana":"いまみやじんじゃひがしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045141,"lng":135.742597,"geo_status":"db","era":"明治14年","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造、瓦葺、間口4.1m、左右潜戸付","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"26-556","desc":"東参道を向いて構える間口四メートルの薬医門で、切妻造本瓦葺である。五平の太い本柱に冠木を渡し、梁を四筋架けて桁を受ける。妻梁上に豕扠首を組み、内側の梁には大瓶束を立てる。左右に築地塀を従え、古社の境内入口に相応しい重厚な趣をもつ大型の門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012208"},{"id":"00013418","register_sub_id":"101","register_pk":"368503","name":"今村家住宅主屋","kana":"いまむらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市東山区本町十丁目157-1","lat":34.98416944,"lng":135.77017778,"geo_status":"db","era":"宝暦12年（1762）頃／明治23年頃・昭和6年頃改修","year":1762,"year_source":"db","year_min":1762,"year_max":1762,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0605","desc":"京都の本町通りに東面して建つ。木造、切妻造桟瓦葺で、外壁は黒漆喰塗、一階に格子を建て、二階に虫籠窓を穿つ。南棟は借家として建て、北棟は南を土間、北を一列三室の座敷とする。改修しているものの、建築、改修年代が明らかで、京都市内で最古級の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013418"},{"id":"00013419","register_sub_id":"101","register_pk":"368504","name":"今村家住宅納屋","kana":"いまむらけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市東山区本町十丁目157-1","lat":34.98417222,"lng":135.77004167,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0606","desc":"敷地中央、主屋の西側背面に位置し、南面して建つ。木造平屋建、切妻造桟瓦葺で、正面に下屋を付す。外壁は白漆喰塗、腰は竪板張で、正面側は開放とする。内部は土間の一室で、茶葉の乾燥に使用したと伝わる。当家の生業の様相を伝える付属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013419"},{"id":"00012958","register_sub_id":"101","register_pk":"368038","name":"入江家住宅主屋","kana":"いりえけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市上京区下立売通御前通西入二丁目堀川町528","lat":35.02098333,"lng":135.73339167,"geo_status":"db","era":"江戸末期／大正7年頃増築、昭和10年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積130㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"26 － 589","desc":"妙心寺道に北面して建つ。東西2棟からなる切妻造桟瓦葺の二階建。東棟は1階に平格子を立て、2階に虫籠窓を穿ち、軒裏まで漆喰で塗込める。土間沿いに四室を並べ、後退して建つ西棟に数寄屋意匠の茶室と座敷を設ける。良質かつ伝統的な構えの町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012958"},{"id":"00012753","register_sub_id":"101","register_pk":"367656","name":"岩井家住宅主屋","kana":"いわいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区雲ケ畑中津川町247","lat":35.13852778,"lng":135.73288194,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（金属板仮葺）、建築面積121㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"26 － 579","desc":"市北部山間にあるもと林家主屋で、南面して建つ。入母屋造茅葺（鉄板仮葺）妻入の平屋建で、正面に土間を取り、東端に台所部を突出する。左右に各3室を配し、東列下手をタナ付の広間、西列上手を座敷とする。市内山間部の最古級の民家として貴重な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012753"},{"id":"00002055","register_sub_id":"101","register_pk":"103045","name":"上田家住宅（町家ぎゃらりー妙芸）主屋","kana":"うえだけじゅうたく（まちやぎゃらりーみょうげい）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市右京区花園木辻南町24-1","lat":35.0209738,"lng":135.72283597,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺、建築面積139㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"26 － 0078","desc":"妙心寺道に北面して建つ。施主は妙心寺出入りの大工で，その弟子が建設にあたったことが判明している。間口５間半規模，東西棟，切妻造，桟瓦葺の町家で，たちが高く，土間上部の架構も繊細で，大正から昭和にかけて普及した近代京町家の特徴をそなえている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002055"},{"id":"00016404","register_sub_id":"101","register_pk":"536471","name":"上田家住宅主屋","kana":"うえだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市下京区仏光寺通新町東入糸屋町220","lat":35.00146389,"lng":135.75758889,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建一部地階付、瓦葺、建築面積193㎡","structure_material":"木造2階建一部地階付","registered":"2025.11.17(令和7.11.17)","register_no":"26 - 0703","desc":"仏光寺通りに南面して建つ、旧白生地問屋の主屋。２階建切妻造桟瓦葺の表屋と居住棟の間に玄関を配した表屋造の形式で、北に二階建の離れを接続する。全体に建ちが高く、正面１階の出格子構えは腰を大判の御影石貼とするなど、時代の流行を伝える近代の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016404"},{"id":"00016405","register_sub_id":"101","register_pk":"536472","name":"上田家住宅土蔵","kana":"うえだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市下京区仏光寺通新町東入糸屋町220","lat":35.00160278,"lng":135.75758611,"geo_status":"db","era":"江戸末期／昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"26 - 0704","desc":"主屋の北に位置する家財蔵。土蔵造2階建切妻造平入桟瓦葺で南に戸口を開け、離れとの間を蔵前とする。外壁モルタル洗出仕上で、目地を切り石造風とする。内部は各階一室の板敷で束立の和小屋を現す。戸口に重厚な鉄扉を構え小規模ながら丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016405"},{"id":"00006871","register_sub_id":"101","register_pk":"107853","name":"胡乱座（旧長岡家住宅主屋）","kana":"うろんざ（きゅうながおかけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市下京区醒ヶ井通綾小路下る要法寺町427","lat":35.001991,"lng":135.75293,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積69㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"26 － 0279","desc":"醒ヶ井通に西面して建つ。桁行３間梁間６間、切妻造桟瓦葺、平入２階建町家で、南側に通りニワを通し、北側床上は４畳半と６畳、６畳の３室を一列に並べ、トコまわりに数寄屋風を加味する。表は１階を出格子、ニワ上部に虫籠窓を配する。近代の京町家の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006871"},{"id":"00003268","register_sub_id":"101","register_pk":"104258","name":"大河内山荘持仏堂","kana":"おおこうちさんそうじぶつどう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市右京区嵯峨小倉山田淵山町8-29他","lat":35.01611866,"lng":135.6696961,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積6.0㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"26 － 0151","desc":"苑内の南西部に東面して建つ。正面１間，側面２間，入母屋造，桟瓦葺，妻入で，正側面３方に刎高欄付切目縁を回す。円柱を頭貫，内法長押で固め，台輪上に三斗組，中備蟇股を置く。小規模だが，軒は吹寄垂木を１支おきに疎らに配すなど，全体に技巧的な造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003268"},{"id":"00003266","register_sub_id":"101","register_pk":"104256","name":"大河内山荘大乗閣","kana":"おおこうちさんそうだいじょうかく","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市右京区嵯峨小倉山田淵山町8-29他","lat":35.01726955,"lng":135.66934757,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、檜皮葺一部茅葺・柿葺及び瓦葺、建築面積131㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"26 － 0149","desc":"大河内傳次郎が営んだ別荘の中心施設。数寄屋風の書院をはじめとして，泉殿のように突出した寝殿，如庵写しの小間の茶室，民家風の勝手，土間を一体化させた斬新な建物。各様式の特性に応じ屋根形式や意匠に工夫を凝らした数寄屋師笛吹嘉一郎の代表作になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003266"},{"id":"00003269","register_sub_id":"101","register_pk":"104259","name":"大河内山荘中門","kana":"おおこうちさんそうちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区嵯峨小倉山田淵山町8-29他","lat":35.01693,"lng":135.66957886,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造、檜皮葺、間口1.7m","structure_material":"木造","registered":"2003.03.18(平成15.03.18)","register_no":"26 － 0152","desc":"庭園の内外郭を区切る位置に建つ門。親柱，控柱，冠木で軸部を構成し，その上に大きく弓形に曲げた垂木を配して迫持状の檜皮葺屋根を載せる。間口約１．７ｍの小規模な門だが，丸太や名栗の部材を多用した数寄屋風の意匠で，奇巧性に富んだ特異な形式になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003269"},{"id":"00003267","register_sub_id":"101","register_pk":"104257","name":"大河内山荘滴水庵","kana":"おおこうちさんそうてきすいあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市右京区嵯峨小倉山田淵山町8-29他","lat":35.01652435,"lng":135.66934748,"geo_status":"db","era":"明治期／昭和7移築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、茅葺一部瓦葺及び柿葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"26 － 0150","desc":"大乗閣の南方庭園内にある茶屋。平屋建で，桁行５間，梁間２間，入母屋造，茅葺の主体部の南面西半に，切妻造，土庇付の突出部をもつ。２室の広間の茶室と土間のある水屋は，丸太や竹を多用した軽快な数寄屋風の造りになり，苑内の景観形成に欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003267"},{"id":"00013582","register_sub_id":"101","register_pk":"504945","name":"太田喜二郎家住宅主屋兼アトリエ","kana":"おおたきじろうけじゅうたくおもやけんあとりえ","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市上京区室町通上立売上る東入柳図子町333他","lat":35.03235,"lng":135.75911111,"geo_status":"db","era":"大正13年／昭和6年増築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積150㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0610","desc":"烏丸通に東面する敷地に建つ洋画家のアトリエ付住宅。主体部は藤井厚二設計。食堂を中心に、東に舟底天井の応接室とアトリエ、南にサンルーム、西に家政部を配する。食堂の三畳大の上段や長椅子等の造付け家具、内装の幾何意匠等に藤井の作風が看取される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013582"},{"id":"00003992","register_sub_id":"101","register_pk":"104982","name":"大原茶屋（田中家住宅）","kana":"おおはらちゃや（たなかけじゅうたく）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市左京区大原来迎院町275","lat":35.11813,"lng":135.83252,"geo_status":"db","era":"江戸後期／明治11曳家改造","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"26 － 0162","desc":"大原三千院の門前通りに南面する農家住宅。木造平屋建，入母屋造茅葺の四周に桟瓦葺の庇を巡らす。桁行６間梁間４間規模の食違いのある四間取平面で，正面右手に土間を配す。現在は土産物店として活用されており，内外ともに農家の佇まいを良好に残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003992"},{"id":"00004269","register_sub_id":"101","register_pk":"105259","name":"大山崎山荘旧車庫（京都府休憩所）","kana":"おおやまざきさんそうきゅうしゃこ（きょうとふきゅうけいじょ）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字銭原5-2","lat":34.89470766,"lng":135.67917831,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造及び木造2階建、瓦葺、建築面積61㎡","structure_material":"鉄筋コンクリート造及び木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"26 － 0180","desc":"鉄筋コンクリート造の１階の前方に張り出して木造２階をのせ，軒及び螻羽を大きく出した切妻造，桟瓦葺の屋根を妻入にかける。１階は車庫，２階は畳敷３室と板敷の台所を配した居室とする。壁面に化粧積煉瓦積を見せたハーフティンバーの印象的な外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004269"},{"id":"00004268","register_sub_id":"101","register_pk":"105258","name":"大山崎山荘栖霞楼（物見塔）","kana":"おおやまざきさんそうせいかろう（ものみのとう）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字銭原5-5","lat":34.89596283,"lng":135.67912848,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積12㎡","structure_material":"木造3階建","registered":"2004.07.23(平成16.07.23)","register_no":"26 － 0179","desc":"敷地北奥の高台に南面して建つ。３ｍ×４ｍほどの矩形平面の小塔で，木造３階建，急勾配の切妻造，鉄板葺の屋根をかける。１階の円形，アーチ形などの出入口，２階南面の縦長窓，３階展望室の大きく開いた横長窓など，多彩な開口部をもつ遊び心あふれる建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004268"},{"id":"00004270","register_sub_id":"101","register_pk":"105260","name":"大山崎山荘琅洞（トンネル）","kana":"おおやまざきさんそうろうかんどう（とんねる）","category":"住宅","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字上ノ田5-1","lat":34.89524421,"lng":135.68070042,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"煉瓦造、延長5.6m、幅員3.6m","structure_material":"煉瓦造","registered":"2004.07.23(平成16.07.23)","register_no":"26 － 0181","desc":"敷地の南東隅部，山荘への進入路として設けられたトンネル。延長５．６ｍ，幅員３．６ｍ，岩盤をくり抜いて煉瓦造躯体でフラットアーチ形に築き，正面側坑門は切石積とする。小規模だが，内部覆工の煉瓦積に焼過ぎ煉瓦を織りまぜるなど，装飾的な造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004270"},{"id":"00013278","register_sub_id":"101","register_pk":"366267","name":"小川家北白川別邸表門","kana":"おがわけきたしらかわべっていおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区北白川小倉町50-10","lat":35.03088056,"lng":135.788625,"geo_status":"db","era":"昭和9年頃","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、銅板葺、間口1.8m、両側袖塀付","structure_material":"木造","registered":"2020.04.03(令和2.04.03)","register_no":"26 － 0597","desc":"敷地南東隅に位置する間口三間の腕木門。中央間を板戸とし、両脇間を板壁とする。欄間に疎らな竪格子を入れ、両端柱の腕木で桁を支え、銅板葺の屋根を載せる。床は石敷きで、中央に巨石を据える。端正な意匠でまとめ、昭和初期の住宅の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013278"},{"id":"00013277","register_sub_id":"101","register_pk":"366266","name":"小川家北白川別邸主屋","kana":"おがわけきたしらかわべっていおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区北白川小倉町50-10","lat":35.03098889,"lng":135.78845556,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積156㎡、板塀付","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"26 － 0596","desc":"北白川の住宅地に建つ藤井厚二設計の隠居屋。木造平屋建で、南東の玄関から西へ庭園に面し茶の間、居間、寝室、閑室が雁行して並ぶ。和室、洋室とも和の要素を直線的な構成で自由に組み合わせ、特に床の間に創意を凝らすなど、藤井の作風が現れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013277"},{"id":"00005623","register_sub_id":"101","register_pk":"106611","name":"小川家住宅主屋","kana":"おがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市左京区鹿ヶ谷下宮ノ前町26","lat":35.01810156,"lng":135.79440501,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造2階建、銅板葺、建築面積156㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"26 － 0210","desc":"敷地の北東に位置する建築面積１５６㎡，切妻造，銅板葺のＲＣ造２階建。外壁は薄茶のドイツ壁風仕上げで，腰を擬石張とし，玄関や２階窓周り等をタイルで飾る。我が国のＲＣ造住宅の早期の事例になり，庭園と共に鹿ヶ谷界隈の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005623"},{"id":"00009640","register_sub_id":"101","register_pk":"194636","name":"梶田家住宅表蔵","kana":"かじたけじゅうたくおもてぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区笹屋町通千本西入笹屋4-285","lat":35.02818645,"lng":135.7411713,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積13㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"26 － 0419","desc":"主屋の表屋西隣に東西棟で建つ。桁行三・八メートル梁間三・四メートル、土蔵造二階建、切妻造本瓦葺で、南面の中庭に出入口を開き、庇を付ける。通りに面する北面では外壁と一体的に桟瓦葺の高塀を表し、腰を竪板張として表屋の外観と調和を図っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009640"},{"id":"00009641","register_sub_id":"101","register_pk":"194637","name":"梶田家住宅雑物蔵","kana":"かじたけじゅうたくざつものぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区笹屋町通千本西入笹屋4-285","lat":35.02797943,"lng":135.74124507,"geo_status":"db","era":"明治45頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"26 － 0420","desc":"主屋の通土間後方に東西棟で建ち、桁行四・七メートル梁間四メートル、土蔵造二階建、切妻造桟瓦葺である。北面を戸口として庇を付け、外壁漆喰塗で北面は腰を竪板張とする。東面上下階と二階北面に窓を穿ち、漆喰塗り丁寧に仕上げた持送り付の庇を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009641"},{"id":"00009639","register_sub_id":"101","register_pk":"194635","name":"梶田家住宅主屋","kana":"かじたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区笹屋町通千本西入笹屋4-285","lat":35.02808413,"lng":135.74121889,"geo_status":"db","era":"明治45頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積198㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"26 － 0418","desc":"通りに北面する表屋造の町家。表屋は正面に出格子を設け、揚げ見世を残し、二階は黒漆喰仕上げで虫籠窓を穿つ。西端に表蔵を並べ建てる。玄関や中庭を介して建つ居住棟は二階建で、東に通土間を配し居室部は中央に廊下を通す。洗練されたつくりの京町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009639"},{"id":"00001717","register_sub_id":"101","register_pk":"102707","name":"河井寬次郎記念館（旧河井寬次郎邸）小間","kana":"かわいかんじろうきねんかん（きゅうかわいかんじろうてい）こま","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市東山区馬町通大和大路東入鐘鋳町569他","lat":34.99346266,"lng":135.77442424,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"26 － 0063","desc":"簀子天井の二畳の間と井戸を設けた土間からなり、併設されていた水屋は現在撤去されている。民家風の太い材料を用いた茶室建築として特色がある。茶を点てたことはなく思索の場として用いられたと言う。主屋と同時期の建築と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001717"},{"id":"00001715","register_sub_id":"101","register_pk":"102705","name":"河井寬次郎記念館（旧河井寬次郎邸）主屋","kana":"かわいかんじろうきねんかん（きゅうかわいかんじろうてい）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市東山区馬町通大和大路東入鐘鋳町569他","lat":34.99357455,"lng":135.7743799,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積148㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"26 － 0061","desc":"陶芸家河井寛次郎の居宅兼工房として建設、寛次郎自身の設計と伝える。主屋は寄棟造妻入で出桁造の建築に千本格子や矢来など京都の町家の意匠を取り入れ、囲炉裏付の板敷広間の空間構成や古色仕上げの材、漆塗りの建具などに独自の住宅観や美意識を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001715"},{"id":"00001716","register_sub_id":"101","register_pk":"102706","name":"河井寬次郎記念館（旧河井寬次郎邸）陶房","kana":"かわいかんじろうきねんかん（きゅうかわいかんじろうてい）とうぼう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市東山区馬町通大和大路東入鐘鋳町569他","lat":34.99347466,"lng":135.77456052,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"26 － 0062","desc":"土間（現休憩室）と板間の２室からなる平屋。板間は椅子式生活用の低床部と、座敷生活用の高床部とに分かれ、高床部に轆轤を置いていた。主屋新築に先立って建設されたと伝える。室内床を二段構成とする手法は主屋の広間とも共通する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001716"},{"id":"00008510","register_sub_id":"101","register_pk":"134906","name":"河合家住宅表門及び高塀","kana":"かわいけじゅうたくおもてもんおよびたかへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府長岡京市粟生梶ケ前19","lat":34.93635052,"lng":135.6789508,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造、瓦葺、延長6.5m","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0362","desc":"街道沿いの高塀で、南端で西に折れる。折れ曲がり六・五メートル。延石に方柱をたて、地覆で固め、腕木を出し、塀瓦を葺く。正面は三間に分け、中央間を表門とし、小庇を付け、格子戸をたてる。他は腰板壁、上部漆喰仕上げとする。街道沿いの景観要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008510"},{"id":"00008508","register_sub_id":"101","register_pk":"134904","name":"河合家住宅主屋","kana":"かわいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府長岡京市粟生梶ケ前19","lat":34.93640283,"lng":135.67909997,"geo_status":"db","era":"江戸後期／明治中期増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0360","desc":"丹波街道沿いの集落、街道東に敷地を占める。西面する正面一三メートルの木造平屋建。切妻造桟瓦葺とし、西・南・東面に深い下屋庇をまわし、西面北端に便所などを付設。北寄りに二列に居室を配し、北列に仏間と座敷を並べる。乙訓地方における大型農家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008508"},{"id":"00008512","register_sub_id":"101","register_pk":"134908","name":"河合家住宅築地塀","kana":"かわいけじゅうたくついじべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府長岡京市粟生梶ケ前19","lat":34.93647368,"lng":135.67917708,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土塀、瓦葺、延長10m","structure_material":"土塀","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0364","desc":"主屋座敷前の庭をＬ字型に囲む築地塀で、隅折れ曲がり延長一〇メートルを測る。野積石垣上に設けられ、壁を漆喰仕上げとする。上部を桟瓦で葺き、棟は低い熨斗積とする。高さを低く抑え、座敷から庭越しに醍醐の山並みを望めるよう配慮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008512"},{"id":"00008509","register_sub_id":"101","register_pk":"134905","name":"河合家住宅土蔵","kana":"かわいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府長岡京市粟生梶ケ前19","lat":34.93639606,"lng":135.67895377,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0361","desc":"敷地の西北隅に東面して建つ。桁行四・九メートル梁間三・九メートルの土蔵造二階建。切妻造桟瓦葺の置屋根とし、東面に庇を付ける。外壁は漆喰塗で、妻は鉢巻まで、西面は腰高に竪板を張る。重厚な外観で、主屋とともに敷地景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008509"},{"id":"00008511","register_sub_id":"101","register_pk":"134907","name":"河合家住宅露地門及び仕切り塀","kana":"かわいけじゅうたくろじもんおよびしきりべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府長岡京市粟生梶ケ前19","lat":34.9363929,"lng":135.67901159,"geo_status":"db","era":"大正期／昭和前期改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"露地門 木造、竹葺、間口1.4m 仕切り塀 土塀、延長3.0m","structure_material":"露地門 木造","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0363","desc":"主屋と土蔵との間に露地門と仕切り塀が東西に続き、庭を間仕切る。仕切り塀は延長三・〇メートルの練塀で、東端、主屋式台脇に接して露地門が建つ。間口一・四メートルの腕木門。屋根は切妻造、孟宗竹を半割にして輪違いに並べて葺く、珍しい仕様になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008511"},{"id":"00001719","register_sub_id":"101","register_pk":"102709","name":"河井寬次郎記念館（旧河井寬次郎邸）素焼窯","kana":"かわいこうじろうきねんかん（きゅうかわいこうじろうてい）すやきがま","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市東山区馬町通大和大路東入鐘鋳町569他","lat":34.99345566,"lng":135.77447738,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"煉瓦造、奥行き1.8m、幅1.6m","structure_material":"煉瓦造","registered":"2000.04.28(平成12.04.28)","register_no":"26 － 0065","desc":"陶房の東に隣接する木造平屋建の土間内にあるレンガ造の窯。登り窯での本焼行程の前に成形した陶土を素焼きするための施設。寛次郎の設計により窯築職人が築造したものと言われる。陶房・登り窯と一連の工房施設として重要な構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001719"},{"id":"00013583","register_sub_id":"101","register_pk":"504946","name":"川端彌之助家住宅主屋兼アトリエ","kana":"かわばたやのすけけじゅうたくおもやけんあとりえ","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市左京区聖護院中町5-4","lat":35.02019722,"lng":135.78105833,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0611","desc":"聖護院北側の敷地奥に建つ洋画家の住宅。南北棟の切妻大屋根の東に切妻屋根を張出し、赤色洋瓦を葺く。大屋根部の北半を占める吹抜のアトリエは内部漆喰塗で北面に大窓を開き、南半に応接間、張出部に玄関や水回りを配す。戦前のアトリエ付住宅の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013583"},{"id":"00005283","register_sub_id":"101","register_pk":"106271","name":"喜多家住宅主屋","kana":"きたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市左京区北白川伊織町54","lat":35.03526942,"lng":135.788864,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積75㎡","structure_material":"木造2階一部平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"26 － 0207","desc":"京都で最初期に形成された郊外住宅地，北白川疏水通の東側に位置する藤井厚二の設計になる住宅。木造２階建，真壁造で，桟瓦葺の屋根を巧みに架け，和風の端正な外観に変化をもたせる。平面構成は合理性に富み，内部は和洋折衷の手法で纏められている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005283"},{"id":"00002554","register_sub_id":"101","register_pk":"103544","name":"北村美術館四君子苑表門","kana":"きたむらびじゅつかんしくんしえんおもてもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区御車道通清和院口上る梶井町448-4","lat":35.02797776,"lng":135.77017914,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"26 － 0096","desc":"長屋門形式ながら格式ばった構えとせず，細い?丸太の柱・梁を用い，緩い勾配の桟瓦葺切妻屋根をかけ数寄を凝らした造りとする。疎らに配した丸太垂木上に丸竹を密に打ち並べた化粧屋根裏や，門口上小壁のむしこ窓風の欄間など，随所に斬新な意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002554"},{"id":"00013276","register_sub_id":"101","register_pk":"366265","name":"北村美術館四君子苑主屋","kana":"きたむらびじゅつかんしくんしえんおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"京都府","address":"京都府京都市上京区御車道通清和院口上る梶井町448-4","lat":35.02803333,"lng":135.77042778,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建一部地階付及び木造平屋建、瓦葺、建築面積205㎡","structure_material":"鉄筋コンクリート造平屋一部2階建一部地階付及び木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"26 － 0595","desc":"実業家北村謹次郎の元自邸。鉄筋コンクリート造で、庭側に和室、北に洋室の居間、二階に茶室を配す。照明を組込んだ天井をフラットに仕上げ、天井高いっぱいの障子など、近代主義的な外観に和風要素を巧みに取入れる。吉田五十八による近代数寄屋住宅の名作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013276"},{"id":"00002553","register_sub_id":"101","register_pk":"103543","name":"北村美術館四君子苑玄関・寄付","kana":"きたむらびじゅつかんしくんしえんげんかん・よりつき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区御車道通清和院口上る梶井町448-4","lat":35.02796121,"lng":135.77031376,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建、瓦葺一部檜皮葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"26 － 0095","desc":"洋間の室礼で立礼席にもなる寄付を中心に，その周囲に玄関，鞘の間，瓦四半敷の廊下を配す。玄関内部は飛石を配して内露地風に造り，上り口の小部屋には躙口をあけ，丸炉を切った珍しい趣向を見せる。茶の湯の施設として使用しうる構成で，外観も軽快に造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002553"},{"id":"00002552","register_sub_id":"101","register_pk":"103542","name":"北村美術館四君子苑離れ茶席","kana":"きたむらびじゅつかんしくんしえんはなれちゃせき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区御車道通清和院口上る梶井町448-4","lat":35.02790784,"lng":135.77065857,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建、瓦葺一部檜皮葺、建築面積109㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"26 － 0094","desc":"苑の最奥に独立して建つ。２畳台目中板入の小間（珍散蓮）と広間・次の間からなる座敷を構え，その間に水屋を配する。小間は相伴席，貴人口を備えるなど技巧を凝らした構成を創意に満ちた巧妙な手法で処理する。広間は地味な造りだが穏和で上質な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002552"},{"id":"00002555","register_sub_id":"101","register_pk":"103545","name":"北村美術館四君子苑渡廊下・外腰掛","kana":"きたむらびじゅつかんしくんしえんわたりろうか・そとこしかけ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区御車道通清和院口上る梶井町448-4","lat":35.02790414,"lng":135.77046293,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"26 － 0097","desc":"寄付から東に延びた四半敷廊下と，離れ茶席に付随する外腰掛からなる。渡廊下は途中折れたり梁間を広げ変化を付ける。外腰掛は貴人席と相伴席をもち，天井は竹の隅木・垂木で化粧屋根裏を造る。簡素だが技巧を凝らした構成には名工北村捨次郎の作意が溢れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002555"},{"id":"00004990","register_sub_id":"101","register_pk":"105980","name":"衣笠会館","kana":"きぬがさかいかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市北区北野下白梅町29","lat":35.026371,"lng":135.730759,"geo_status":"db","era":"明治38頃","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積138㎡","structure_material":"煉瓦造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"26 － 0199","desc":"北区南部，西大路通から西側に入った敷地に建つ。桁行１３ｍ，梁間９．３ｍの煉瓦造２階建で，イギリス積とする。胴蛇腹とデンティル付軒蛇腹を四周にあしらい，縦長窓上部の欠円アーチ形を建具等にも用いるなど，統一性のあるデザインとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004990"},{"id":"00016514","register_sub_id":"101","register_pk":"574876","name":"衣笠山の家（小林家住宅）主屋","kana":"きぬがさやまのいえ（こばやしけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"京都府","address":"京都府京都市北区衣笠衣笠山町7-9","lat":35.03608694,"lng":135.72413083,"geo_status":"db","era":"昭和39年","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積196㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"26 - 0709","desc":"衣笠山の山麓に位置する住宅主屋。設計は増田友也。芝庭に面した傾斜地に建つ鉄筋コンクリート造２階建で1階正面はピロティとする。外壁はコンクリート打放仕上で東・西の壁面はタイル貼。室内は襖・障子・長押など随所に和風の意匠でまとめた増田の代表作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016514"},{"id":"00016515","register_sub_id":"101","register_pk":"574877","name":"衣笠山の家（小林家住宅）正門","kana":"きぬがさやまのいえ（こばやしけじゅうたく）せいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"京都府","address":"京都府京都市北区衣笠衣笠山町7-9","lat":35.03608694,"lng":135.72413083,"geo_status":"db","era":"昭和39年頃","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造、間口3.0m、西袖付","structure_material":"鉄筋コンクリート造","registered":"2026.02.10(令和8.02.10)","register_no":"26 - 0710","desc":"敷地南面の東端に建つ正門。門柱は鉄筋コンクリート造で、塀状に延ばした平面とし、表面は荒く仕上げた花崗岩貼とする。門口には格子風に内部を透かした鉄製の門扉を構える。全体に高さを低く抑えた外観が周囲の景観と調和し、主屋へのアプローチを演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016515"},{"id":"00010980","register_sub_id":"101","register_pk":"208950","name":"木村家住宅主屋","kana":"きむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区日暮通下立売上る天秤町598他","lat":35.020327,"lng":135.74792,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積150㎡、塀付","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"26-0495","desc":"西向き敷地の北西隅に洋風の応接間を、前面の高塀から前庭を隔てて居室部を建てる。一階は中廊下式の南北に居室を配して北東隅の主室に上質な座敷飾りを備え、二階にはサンルーム風の広縁を設ける。京都市内における、戦前の住宅思潮を示す洋間付住宅の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010980"},{"id":"00010981","register_sub_id":"101","register_pk":"208951","name":"木村家住宅土蔵","kana":"きむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市上京区日暮通下立売上る天秤町598他","lat":35.020268,"lng":135.748001,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"26-0496","desc":"主屋南東隅に接続する南北棟の二階建土蔵。桁行五・七メートル梁間三・九メートル、切妻造本瓦葺で、西面戸口の下屋で主屋廊下と連絡する。外部は鉢巻を廻らし、腰を竪板張とする。戸口に丁寧な仕上げの漆喰塗戸を開く。屋敷景観に重厚さを添える内蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010981"},{"id":"00010982","register_sub_id":"101","register_pk":"208952","name":"木村家住宅門及び塀","kana":"きむらけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区日暮通下立売上る天秤町598他","lat":35.02030423,"lng":135.7478268,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"門 木造、瓦葺、間口1.8m 塀 木造、瓦葺、総延長11m","structure_material":"門 木造","registered":"2016.02.25(平成28.02.25)","register_no":"26-0497","desc":"敷地西面、主屋の玄関脇に開く門と、折曲がりにのびる塀で、桟瓦葺である。全体の棟高を高めに揃えて小壁を土塗とし、門は内法高を左右の竪板張の水切と一連として引違いの格子をたて、正背面にやや深い庇を付ける。大塀造町家の類型に連なる瀟洒な門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010982"},{"id":"00014858","register_sub_id":"101","register_pk":"519118","name":"旧井関家住宅（青柳家住宅）主屋","kana":"きゅういせきけじゅうたく（あおやぎけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市上京区寺之内通大宮西入大猪熊町75","lat":35.03396389,"lng":135.74735833,"geo_status":"db","era":"江戸末期／明治中期・令和3年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積78㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0658","desc":"西陣の寺之内通りに北面する町家。つし二階建切妻造平入で、一階は出格子構えとし、二階は虫籠窓を二箇所開ける。内部は東に土間を通して西に三室並べ、南の土間上部を吹抜とした織屋建形式の平面を残す。西陣にあって江戸時代の織屋の様相を示す貴重な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014858"},{"id":"00012758","register_sub_id":"101","register_pk":"367661","name":"旧上田家住宅内蔵","kana":"きゅううえだけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府向日市鶏冠井町東井戸64-2","lat":34.94271194,"lng":135.70610694,"geo_status":"db","era":"明治43年頃／昭和17年頃移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"26 － 584","desc":"離れの西側に並び、主屋背面に接続して建つ家財蔵。土蔵造二階建、切妻造桟瓦葺で南面に戸口を設ける。外壁は漆喰塗で鉢巻三段を廻し、鉢巻下を縦板張で養生する。内部は上下階とも板敷、小屋は登梁である。敷地西北隅にあって集落の街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012758"},{"id":"00012756","register_sub_id":"101","register_pk":"367659","name":"旧上田家住宅主屋","kana":"きゅううえだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府向日市鶏冠井町東井戸64-2","lat":34.94271194,"lng":135.70610694,"geo_status":"db","era":"明治43年／昭和17年頃移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積168㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"26 － 582","desc":"市中央部の集落にある農家で、主屋は敷地中央に南面して建つ。切妻造桟瓦葺の平屋建で四周に下屋を廻し、正面下屋上に虫籠窓を穿つ。東に土間、西の前後に各2室を配し、前列奧に座敷を設ける。伝統民家の形式を踏襲し、集落の歴史的景観の核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012756"},{"id":"00012759","register_sub_id":"101","register_pk":"367662","name":"旧上田家住宅外蔵","kana":"きゅううえだけじゅうたくそとぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府向日市鶏冠井町東井戸64-2","lat":34.94271194,"lng":135.70610694,"geo_status":"db","era":"明治43年頃／昭和17年頃移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"26 － 585","desc":"敷地東方に西面して建つ。土蔵造二階建、切妻造桟瓦葺で南半を落棟の平屋建とし、西面に下屋を通して南端に角屋の小室を設ける。主体部は米蔵で上下階とも板敷とし、1階北半を壁トタン張とする。落棟は道具蔵で土間とする。農家の構成に欠かせない附属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012759"},{"id":"00012760","register_sub_id":"101","register_pk":"367663","name":"旧上田家住宅中門及び塀","kana":"きゅううえだけじゅうたくちゅうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府向日市鶏冠井町東井戸64-2","lat":34.94271194,"lng":135.70610694,"geo_status":"db","era":"昭和17年頃","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"中門 木造、瓦葺、間口1.0m 塀 木造、瓦葺、総延長27m","structure_material":"中門 木造","registered":"2019.03.29(平成31.03.29)","register_no":"26 － 586","desc":"主屋前庭の東西南三面を区切る塀と東面塀の北寄りに開く門。塀はモルタル洗出し仕上の布基礎上に建つ真壁造の腰縦板張で、桟瓦葺の屋根を載せる。門は間口1メートル、切妻造桟瓦葺の棟門で両開きの板扉を備える。主屋正面の構えを格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012760"},{"id":"00012757","register_sub_id":"101","register_pk":"367660","name":"旧上田家住宅離れ","kana":"きゅううえだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府向日市鶏冠井町東井戸64-2","lat":34.94271194,"lng":135.70610694,"geo_status":"db","era":"昭和17年頃","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造2階建、瓦葺、建築面積39㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"26 － 583","desc":"主屋背面に接続して建つ。入母屋造桟瓦葺の二階建、一階は続き間の座敷で南東二面に下屋を廻して縁を設ける。二階は8畳の居室と納戸を設ける。外壁は真壁造の漆喰塗、隣地に面する背面を縦板張とする。主屋とともに伝統的な屋敷構えの中心部を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012757"},{"id":"00005624","register_sub_id":"101","register_pk":"106612","name":"旧上田恒次家住宅主屋","kana":"きゅううえだつねじけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岩倉木野町170","lat":35.072224,"lng":135.777725,"geo_status":"db","era":"昭和12／昭和17頃増築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積145㎡、地階付","structure_material":"木造平屋一部2階建","registered":"2006.08.03(平成18.08.03)","register_no":"26 － 0211","desc":"敷地北側に南面して建つ。桁行１０間半，梁間３間半で，木造一部２階建，切妻造，桟瓦葺の陶芸家の工房兼住宅。外壁は漆喰仕上で，腰を下見板張とする。木部は弁柄塗で，梁の小口を胡粉で飾り，東側増築部分のみ墨で黒く拭く。伝統的な民家意匠の外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005624"},{"id":"00005629","register_sub_id":"101","register_pk":"106617","name":"旧上野家住宅馬屋","kana":"きゅううえのけじゅうたくうまや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府舞鶴市西方寺285","lat":35.44545923,"lng":135.21585531,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積30㎡","structure_material":"土蔵造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"26 － 0216","desc":"主屋の南西方，長屋門の南東方に建つ。桁行２間半，梁間２間の規模で，東西棟，切妻造，桟瓦葺の土蔵造平屋建とする。外壁は竪板張とし，上部を中塗り仕上げとし，両妻に小窓を開く。開口部に改造が見られるものの，屋敷正面の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005629"},{"id":"00005627","register_sub_id":"101","register_pk":"106615","name":"旧上野家住宅主屋","kana":"きゅううえのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府舞鶴市西方寺285","lat":35.44559796,"lng":135.215866,"geo_status":"db","era":"天保期","year":1836,"year_source":"estimated","year_min":1830,"year_max":1844,"year_label":"天保期","structure":"木造平屋建、茅葺一部瓦葺、建築面積191㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"26 － 0214","desc":"敷地中央に南面して建つ。桁行９間半，梁間５間の規模で，入母屋造，茅葺の木造平屋建で，桟瓦葺の下屋を四周に廻し，東方にカミノマが突出する。外壁は漆喰仕上げで，腰を竪板張とする。棟を瓦とし，妻を懸魚で飾り，式台を設ける。江戸末期の庄屋の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005627"},{"id":"00005634","register_sub_id":"101","register_pk":"106622","name":"旧上野家住宅神社","kana":"きゅううえのけじゅうたくじんじゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府舞鶴市西方寺285","lat":35.44566339,"lng":135.21601669,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、こけら葺、建築面積1.3㎡、覆屋付","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"26 － 0221","desc":"主屋北東方に東面して建つ。こけら葺の一間社流造の小振りな社殿で，屋敷神を祀る。覆屋付きで，向拝の虹梁絵様，龍の彫刻，木鼻の唐獅子や貘等，入念な仕上げとする。正面の扉を透かすなど，舞鶴地方の特色を見せる。地域の祭事にも使われた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005634"},{"id":"00005631","register_sub_id":"101","register_pk":"106619","name":"旧上野家住宅中蔵","kana":"きゅううえのけじゅうたくなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府舞鶴市西方寺285","lat":35.44566071,"lng":135.21572706,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"26 － 0218","desc":"東蔵の西方に並んで建つ。桁行４間半，梁間２間規模，東西棟，切妻造，桟瓦葺の土蔵造２階建。内部は２間半と２間に仕切られ，それぞれ南面に扉口を構えて，米蔵，味噌蔵として使われた。切石積の土台の上に建ち，正面に土庇をかけ，東蔵と一体的な景観を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005631"},{"id":"00005628","register_sub_id":"101","register_pk":"106616","name":"旧上野家住宅長屋","kana":"きゅううえのけじゅうたくながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府舞鶴市西方寺285","lat":35.44553491,"lng":135.2156779,"geo_status":"db","era":"明治10代","year":1877,"year_source":"converted","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"26 － 0215","desc":"敷地西方に東面して建つ。桁行１１間半，梁間２間規模，南北に棟を置く切妻造，瓦葺の木造平屋建。南面及び西面に半間の下屋を廻し，東面に土庇をかける。外壁は漆喰仕上げで，腰を竪板張とする。北側に座敷を置く長大な平面は，特徴ある敷地景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005628"},{"id":"00005632","register_sub_id":"101","register_pk":"106620","name":"旧上野家住宅西蔵","kana":"きゅううえのけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和中","pref":"京都府","address":"京都府舞鶴市西方寺285","lat":35.44560834,"lng":135.2155037,"geo_status":"db","era":"昭和20代","year":1945,"year_source":"converted","year_min":1945,"year_max":1945,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"26 － 0219","desc":"長屋の北西方に建つ。桁行２間半，梁間２間規模，東西棟，切妻造，桟瓦葺の土蔵造２階建。切石積基礎の上に建ち，南面に扉口を構えて石階段を設け，土庇をかける。外壁は漆喰仕上げとする。屋敷の充実に伴って造られ，屋敷の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005632"},{"id":"00005630","register_sub_id":"101","register_pk":"106618","name":"旧上野家住宅東蔵","kana":"きゅううえのけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府舞鶴市西方寺285","lat":35.44568715,"lng":135.21582218,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"26 － 0217","desc":"主屋背後に建つ。桁行２間，梁間２間規模，東西棟，切妻造，桟瓦葺の土蔵造２階建。平入で，南面に扉口を構え，上に窓を設ける。切石積の土台の上に建ち，外壁は中塗仕上げとし，軒廻りに鉢巻を廻す。正面に土庇をかける。中蔵と共に屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005630"},{"id":"00005633","register_sub_id":"101","register_pk":"106621","name":"旧上野家住宅塀","kana":"きゅううえのけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府舞鶴市西方寺285","lat":35.44556652,"lng":135.21616794,"geo_status":"db","era":"江戸後期／大正期増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、延長44m、門及び厠付","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"26 － 0220","desc":"正面入口から屋敷の南側を廻り，庭園を囲むように北に折れて上野神社に至る。南側中程に厠が付き，そこから庭園西側を限る塀が伸び，庭門を設ける。延長４４ｍ，切妻造，桟瓦葺，木造で，道路側壁面は腰を竪羽目板及びひしゃぎ竹張り，その上部を漆喰塗とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005633"},{"id":"00008716","register_sub_id":"101","register_pk":"149437","name":"旧大野木家住宅主屋","kana":"きゅうおおのぎけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市山科区竹鼻堂ノ前町5-3","lat":34.98796491,"lng":135.81830752,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"converted","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積450㎡","structure_material":"木造2階一部平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"26 － 0365","desc":"通りの東に占める敷地の中央に南面して建つ。玄関や洋間の応接室などからなる棟と座敷の棟を雁行に配する。いずれも木造2階建で、軒の垂木まで塗り込める。屋根は入母屋造本瓦葺の主棟に小屋根を造り付けて、複雑な構成とし、城郭風の重厚な外観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008716"},{"id":"00008721","register_sub_id":"101","register_pk":"149442","name":"旧大野木家住宅北蔵","kana":"きゅうおおのぎけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市山科区竹鼻堂ノ前町5-3","lat":34.98808682,"lng":135.81803262,"geo_status":"db","era":"昭和11年頃","year":1936,"year_source":"converted","year_min":1936,"year_max":1936,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"26 － 0370","desc":"西蔵の南に、南北棟で建つ。切妻造桟瓦葺。桁行5.0ｍ梁間4.0ｍの2階建土蔵。東面に桟瓦葺庇を付け、出入口とし、上部に小庇付の窓を穿つ。外壁は腰板張で、漆喰仕上げとする。庇持送りに鏝仕上げがなされる。伝統的な仕様のなか、鉄製扉を装置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008721"},{"id":"00008720","register_sub_id":"101","register_pk":"149441","name":"旧大野木家住宅護摩堂","kana":"きゅうおおのぎけじゅうたくごまどう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市山科区竹鼻堂ノ前町5-1","lat":34.98815614,"lng":135.81807207,"geo_status":"db","era":"昭和14年頃","year":1939,"year_source":"converted","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積9.9㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"26 － 0369","desc":"東蔵と西蔵の壁に接して建つ。正面1.8ｍ奥行4.0ｍ、両下造桟瓦葺で、前方を葺き降ろす。正面は舟肘木を付け、引違い格子戸をたて、二軒半繁垂木とする。内部は板敷で、天井を漆喰で塗り上げ、中央に排気口を穿つ。住宅に設けられた宗教施設の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008720"},{"id":"00008723","register_sub_id":"101","register_pk":"149444","name":"旧大野木家住宅中門及び塀","kana":"きゅうおおのぎけじゅうたくちゅうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市山科区竹鼻堂ノ前町5-3","lat":34.98780236,"lng":135.81829676,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"中門 木造、瓦葺、間口1.6m 塀 木造、瓦葺、総延長60m","structure_material":"中門 木造","registered":"2011.07.25(平成23.07.25)","register_no":"26 － 0372","desc":"敷地内を南側を画する塀と、その中央から北に延びて、座敷南庭を画する庭塀からなり、総延長60ｍ。屋根瓦葺で、庭塀は腰を木賊張とする。中央に構える中門は、間口1.6ｍ、切妻造桟瓦葺の腕木門で、節付丸太柱を使用。数寄屋風意匠で、景観に安らぎを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008723"},{"id":"00008722","register_sub_id":"101","register_pk":"149443","name":"旧大野木家住宅中蔵","kana":"きゅうおおのぎけじゅうたくなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市山科区竹鼻堂ノ前町5-3","lat":34.98803543,"lng":135.81804219,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"converted","year_min":1941,"year_max":1941,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"26 － 0371","desc":"北蔵の南に、南北棟で建つ。切妻造桟瓦葺。桁行4.0ｍ梁間4.0ｍの2階建土蔵。東面に桟瓦葺庇を付け、掛子塗の両開戸を吊る。東・南面の上部に小庇付の窓を穿つ。外壁は腰板張で、漆喰仕上げとする。敷地西隅に多くの土蔵が連なり、重厚な屋敷構えを構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008722"},{"id":"00008719","register_sub_id":"101","register_pk":"149440","name":"旧大野木家住宅西蔵","kana":"きゅうおおのぎけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市山科区竹鼻堂ノ前町5-1","lat":34.98814658,"lng":135.81802784,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"converted","year_min":1939,"year_max":1939,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"26 － 0368","desc":"東蔵の西に東西棟で建つ。切妻造本瓦葺。桁行五5.0ｍ梁間4.0ｍの2階建土蔵。南面に桟瓦葺庇を付け、掛子塗の両開戸を吊り、上部に小庇付の窓を穿つ。外壁は腰板張で、漆喰仕上げとする。内部は1階を竪板張、2階を漆喰仕上げとする。東蔵と棟高を違える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008719"},{"id":"00008718","register_sub_id":"101","register_pk":"149439","name":"旧大野木家住宅東蔵","kana":"きゅうおおのぎけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市山科区竹鼻堂ノ前町5-1","lat":34.98815853,"lng":135.81810673,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"converted","year_min":1939,"year_max":1939,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"26 － 0367","desc":"主屋座敷の西北に建つ。東西棟の切妻造桟瓦葺。桁行4.0ｍ梁間4.0ｍの二階建土蔵。南面に桟瓦葺庇を付け、掛子塗の両開戸を吊り、上部に小庇付の窓を穿つ。外壁は腰板張で、漆喰仕上げとする。庭園の隅に位置し、景観に落ち着きを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008718"},{"id":"00008717","register_sub_id":"101","register_pk":"149438","name":"旧大野木家住宅物置","kana":"きゅうおおのぎけじゅうたくものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市山科区竹鼻堂ノ前町5-3","lat":34.98796655,"lng":135.81830895,"geo_status":"db","era":"昭和14年／平成15年改修","year":1939,"year_source":"converted","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"26 － 0366","desc":"主屋の東南に位置する。東西棟の入母屋造桟瓦葺。桁行6.4ｍ梁間2.8ｍの木造平屋建。西面には下屋庇をかけ、低い腰掛を設け、待合とする。玄関への通路から見える西面と南面は腰を海鼠壁とし、軒や妻を漆喰で塗り込め、主屋と調和を図っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008717"},{"id":"00014048","register_sub_id":"101","register_pk":"508308","name":"旧梶井宮御門","kana":"きゅうかじいのみやごもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市中京区油小路通二条下る二条油小路町284","lat":35.013025,"lng":135.75335833,"geo_status":"db","era":"元禄16年(1703)／昭和10年・令和元年移築","year":1703,"year_source":"db","year_min":1703,"year_max":1703,"year_label":null,"structure":"木造、瓦葺、間口4.5m","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"26 - 0640","desc":"梶井宮門跡宅から三井家油小路邸に移築された門。間口四・五メートル、本瓦葺の一間一戸薬医門。木太い角柱で、冠木上に梁を四本架け、蓑束に花肘木の三斗で棟を支える。二軒半繁垂木で、梁や垂木鼻は繰型付胡粉塗とする門跡邸宅らしい華やかな意匠で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014048"},{"id":"00009645","register_sub_id":"101","register_pk":"194641","name":"旧片岡家住宅主屋","kana":"きゅうかたおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市右京区鳴滝音戸山町6-38他","lat":35.0302374,"lng":135.70074095,"geo_status":"db","era":"明治43／平成23移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、スレート葺、建築面積102㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"26 － 0424","desc":"木造二階建の洋風住宅。寄棟造スレート葺で、ドーマー窓をあげる。外観はハーフティンバーで北面の玄関ポーチ、東面のベイウインドウ、南面東半のベランダで飾る。軒のブラケットや内部暖炉廻りにアール・ヌーヴォーが薫る。木部の造作も丁寧で上品な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009645"},{"id":"00013828","register_sub_id":"101","register_pk":"507790","name":"旧片岡家住宅主屋","kana":"きゅうかたおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府福知山市字下柳15","lat":35.30277778,"lng":135.12595833,"geo_status":"db","era":"明治元年頃／明治22年増築、令和2年改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造2階建、瓦葺、建築面積164㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"26 － 0634","desc":"福知山城下由良川堤防西の京街道に東面する。桁行五間半梁間六間半、切妻造桟瓦葺。明治元年築の一列三間取を同二二年に北に増築、二列六間取として角屋を設けた。つし二階に格子窓と虫籠窓を開くが、それぞれ意匠を違え、増築による商家の発展過程を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013828"},{"id":"00013833","register_sub_id":"101","register_pk":"507795","name":"旧片岡家住宅高塀","kana":"きゅうかたおかけじゅうたくたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府福知山市字下柳22-1他","lat":35.30290833,"lng":135.125925,"geo_status":"db","era":"大正4年／令和2年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造、瓦葺、延長14.5m","structure_material":"木造","registered":"2021.06.24(令和3.06.24)","register_no":"26 － 0639","desc":"主屋北に敷地北東隅まで通りに面して建ち、二階建離座敷の前庭と通りを区切る。長さ十一間、高さ三メートルで、壁は漆喰塗で腰を板張とし屋根は表は目板瓦葺。中央間に引違格子戸を建て出入口とし桟瓦葺の庇を架ける。北端間に埋込んだ地蔵堂が目を引く高塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013833"},{"id":"00013829","register_sub_id":"101","register_pk":"507791","name":"旧片岡家住宅二階建離座敷","kana":"きゅうかたおかけじゅうたくにかいだてはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府福知山市字下柳15","lat":35.30286667,"lng":135.12579722,"geo_status":"db","era":"大正4年／令和2年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積129㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"26 － 0635","desc":"敷地の北辺に主屋西庭を囲んで建つ。桁行六間梁間三間半入母屋造桟瓦葺。たちの高い総二階建で東面に式台玄関を設ける。座敷飾りを備えた座敷を一階は二室、二階は三室東西に並べ、南側に広縁を介して庭を望む。地元財界人接遇のための本格的書院造の座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013829"},{"id":"00013832","register_sub_id":"101","register_pk":"507794","name":"旧片岡家住宅西土蔵","kana":"きゅうかたおかけじゅうたくにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府福知山市字下柳15","lat":35.30284444,"lng":135.12567222,"geo_status":"db","era":"大正4年／令和2年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積32㎡","structure_material":"土蔵造3階建","registered":"2021.06.24(令和3.06.24)","register_no":"26 － 0638","desc":"二階建離座敷の西、敷地北西隅に建つ。南北棟の土蔵造三階建、切妻造桟瓦葺で南面に板敷の蔵前を設け、離れ座敷の廊下から繋がる。外壁は漆喰塗。二階建離座敷と一連で敷地地盤を約一メートル高め、かつ三階建とするなど、地域特有の水害に備えた特性を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013832"},{"id":"00013830","register_sub_id":"101","register_pk":"507792","name":"旧片岡家住宅平屋離座敷","kana":"きゅうかたおかけじゅうたくひらやはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府福知山市字下柳15","lat":35.302675,"lng":135.12587222,"geo_status":"db","era":"昭和9年／令和2年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"26 － 0636","desc":"主屋南西に建つ。平屋建で西側を切妻造、東側を入母屋造とした桟瓦葺で南に下屋を付す。内部は続き間座敷で北に縁を介して庭を望む。西の六畳は地袋付蹴込床で竹の落掛とし、脇に琵琶床風の棚を設け、平書院に火燈窓を設けるなど、数寄屋風意匠とする離座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013830"},{"id":"00013831","register_sub_id":"101","register_pk":"507793","name":"旧片岡家住宅南土蔵","kana":"きゅうかたおかけじゅうたくみなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府福知山市字下柳15","lat":35.30275,"lng":135.12603889,"geo_status":"db","era":"大正4年／昭和9年移築、令和2年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"26 － 0637","desc":"主屋南に通りに面して建つ。土蔵造二階建、東西棟の切妻造桟瓦葺。北面主屋土間側に出入口を設ける。外壁は漆喰塗で腰を人造石洗出仕上とするが、東面は主屋北面の高塀意匠に合わせ、腰板張に付柱、目板瓦葺の水切庇を付し、通り側の景観に統一性を持たせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013831"},{"id":"00016543","register_sub_id":"101","register_pk":"574905","name":"旧河村家住宅（芸術寺院自然寺）主屋","kana":"きゅうかわむらけじゅうたく（げいじゅつじいんしぜんじ）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府南丹市園部町船岡馬場14","lat":35.14108389,"lng":135.48605694,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積158㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"26 - 0738","desc":"大堰川沿いの農村集落にある旧家の主屋。敷地中央に南面して建つ平屋建入母屋造平入桟瓦葺で三方に下屋を廻す。西に土間、東に２列６室を配し、南面中央に式台を構える。南東の座敷は床廻りに銘木を用い格式を示す。当地域の大規模農家建築の典型を示す民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016543"},{"id":"00016544","register_sub_id":"101","register_pk":"574906","name":"旧河村家住宅（芸術寺院自然寺）長屋門","kana":"きゅうかわむらけじゅうたく（げいじゅつじいんしぜんじ）ながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府南丹市園部町船岡馬場14","lat":35.14108389,"lng":135.48605694,"geo_status":"db","era":"明治前期／平成17年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"26 - 0739","desc":"主屋南方に位置し、通りに南面する長屋門。木造平屋建入母屋造桟瓦葺、外壁は漆喰塗、腰は下見板張で木部は弁柄塗とする。中央の門口にケヤキ一枚板の扉を吊り、西に納屋、東に座敷を配す。正面の出格子が印象的で、主屋とともに当地域の集落景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016544"},{"id":"00016545","register_sub_id":"101","register_pk":"574907","name":"旧神田家住宅主屋","kana":"きゅうこうだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府南丹市美山町鶴ケ岡今安13-1・15合併","lat":35.10743611,"lng":135.46989694,"geo_status":"db","era":"明治14年／令和4年改修","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、茅葺、建築面積210㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"26 - 0740","desc":"周山街道沿いに位置する旧家の主屋。敷地中央に南面して建つ、平屋建入母屋造平入茅葺で、周囲に鉄板葺の下屋を廻らす。内部は西に土間、東に居室を配し、土間沿いの一八畳上部は、縦横に梁を組み天井を張る。茅葺屋根が地域の景観をつくる大規模な民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016545"},{"id":"00015487","register_sub_id":"101","register_pk":"533502","name":"旧子安家住宅主屋","kana":"きゅうこやすけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府亀岡市本町51","lat":35.01046944,"lng":135.57805,"geo_status":"db","era":"江戸末期／平成24年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積89㎡","structure_material":"木造平屋一部2階建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0702","desc":"本町通りに南面して建つ、旧日用品販売業の主屋。つし二階建切妻造妻入桟瓦葺で、正面一階は出格子構え、二階は虫籠窓を開け、庇を付す。内部北はかつての通り土間で、南は４室を並べ、北西を床構え付き座敷。建ちが低く古式で歴史的な景観を形成する町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015487"},{"id":"00007078","register_sub_id":"101","register_pk":"108060","name":"旧小山家住宅（田村屋螢庵）主屋","kana":"きゅうこやまけじゅうたく（たむらやほたるあん）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府南丹市美山町三埜小山ノ元38","lat":35.27513389,"lng":135.50760255,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺、建築面積156㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0300","desc":"小高い山の西麓に占める敷地の後方中央に位置する。入母屋造茅葺で桟瓦葺庇を付設し、西面して建つ。南半部を広い土間とし、北半部に座敷やイタノマ、ナンドを設ける。西面北端が主座敷で、トコや付書院を構える。かつての大庄屋の風格を伝える農家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007078"},{"id":"00007079","register_sub_id":"101","register_pk":"108061","name":"旧小山家住宅（田村屋螢庵）土蔵","kana":"きゅうこやまけじゅうたく（たむらやほたるあん）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府南丹市美山町三埜小山ノ元38","lat":35.27524102,"lng":135.50748983,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積23㎡","structure_material":"土蔵造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0301","desc":"主屋の西北に位置する。東西棟の切妻造桟瓦葺の置屋根で、西面に庇を設け、出入口を開く。桁行６．７ｍ梁間４．５ｍの平屋建土蔵。外壁は漆喰仕上げで、腰竪板を張る。一段高い敷地に主屋と土蔵が並び建つ、堂々とした屋敷構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007079"},{"id":"00007080","register_sub_id":"101","register_pk":"108062","name":"旧小山家住宅（田村屋螢庵）庭門及び塀","kana":"きゅうこやまけじゅうたく（たむらやほたるあん）にわもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府南丹市美山町三埜小山ノ元38","lat":35.27512867,"lng":135.50748873,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"門 木造、瓦葺、間口1.2m、袖塀付 塀 木造、杉皮葺、延長13m、木戸門付","structure_material":"門 木造","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0302","desc":"主屋西面に東西棟で建つ１間棟門で、背面に控柱を建てる。切妻造桟瓦葺で、両開板戸をたて、主屋寄りの塀に潜りを設ける。門西柱から土蔵までの間にコの字型に塀が延びる。腰竪板張の真壁造で、屋根を杉皮で葺く。主座敷前の庭園を区画し、落ち着きを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007080"},{"id":"00009994","register_sub_id":"101","register_pk":"196141","name":"旧武田家住宅主屋","kana":"きゅうたけだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市下京区高辻通油小路東入永養寺町242-1","lat":34.99995519,"lng":135.75459831,"geo_status":"db","era":"明治前期／大正5改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積131㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0450","desc":"高辻通に北面する表屋造の町家。表屋の正面一階は出格子と平格子で構成し、二階は土塗の大壁に横長の窓を開ける。大正初期の居住部は上下階とも八畳を主室とし、座敷飾に数寄屋風を加味し、廻り階段を二箇所設けるなど、内部造作に趣向を凝らす、上質な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009994"},{"id":"00011526","register_sub_id":"101","register_pk":"210476","name":"旧邸御室主屋","kana":"きゅうていおむろしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区御室岡ノ裾町5","lat":35.02563611,"lng":135.71207,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋2階建、瓦葺一部銅板葺、建築面積238㎡","structure_material":"木造平屋2階建","registered":"2017.05.02(平成29.05.02)","register_no":"26-0515","desc":"木造二階建、桟瓦葺で、一階は北東隅に玄関を開き、矩折れの廊下を南北に通してその西に一二畳半の座敷と一〇畳を設ける。廊下の東側は内向きの空間とする。二階には八畳三室を設ける。意匠を凝らした座敷廻りなど、内外ともに質の高い近代和風住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011526"},{"id":"00011528","register_sub_id":"101","register_pk":"210478","name":"旧邸御室茶室双庵","kana":"きゅうていおむろちゃしつならびあん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区御室岡ノ裾町5","lat":35.02541694,"lng":135.71226889,"geo_status":"db","era":"昭和12年頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"26-0517","desc":"双ヶ岡の北斜面に位置する敷地の、南東隅の小高い位置に建つ。木造平屋建、桟瓦葺で、四畳半の東側に平床と主人席を配し、さらに東端に水屋を設ける。茶室北面には付書院状の窓を開き、御室の風景を一望できる。開放的なつくりの茶室である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011528"},{"id":"00011527","register_sub_id":"101","register_pk":"210477","name":"旧邸御室土蔵","kana":"きゅうていおむろどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区御室岡ノ裾町5","lat":35.02575889,"lng":135.71200306,"geo_status":"db","era":"昭和12年頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"26-0516","desc":"敷地北西隅に建つ。主屋北西隅に後補部分を介して接続する。土蔵造二階建、本瓦葺で、二間四方の正方形平面を有する。外壁は漆喰仕上で、東・北面の腰部は竪板張。小屋組はヒノキ材の和小屋である。良材を用いた丁寧な造りの土蔵で、敷地内外の景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011527"},{"id":"00011529","register_sub_id":"101","register_pk":"210479","name":"旧邸御室待合","kana":"きゅうていおむろまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市右京区御室岡ノ裾町5","lat":35.02537,"lng":135.71220111,"geo_status":"db","era":"昭和12年頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積4.8㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"26-0518","desc":"茶室の西方に建つ。屋根は銅板葺で、棟のみ瓦を積む。北に向けて腰掛を配し、その奥に一畳敷を置き、その西は壁に丸窓、東には水屋を設ける。南流れの屋根垂木を丸桁で受け、奇木を用い、壁に台形の切込みを入れるなど、意匠を凝らした待合である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011529"},{"id":"00011530","register_sub_id":"101","register_pk":"210480","name":"旧邸御室門及び塀","kana":"きゅうていおむろもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区御室岡ノ裾町5","lat":35.025788,"lng":135.712041,"geo_status":"db","era":"昭和12年頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"門 木造、瓦葺、間口3.5m 塀 木造、瓦葺、総延長62m","structure_material":"門 木造","registered":"2017.05.02(平成29.05.02)","register_no":"26-0519","desc":"敷地北面から西面北寄りを画す塀の北面に門を開く。門は切妻造桟瓦葺で、引戸は上部に桟を入れ、外面にナグリを施す意匠を見せる。北面の塀は真壁に瓦葺とし、西面も同様であるが、土台を舟肘木状の部材で受けるなど、全体として特色ある意匠を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011530"},{"id":"00013826","register_sub_id":"101","register_pk":"507788","name":"旧寺江家住宅店舗及び主屋","kana":"きゅうてらえけじゅうたくてんぽおよびおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区新町通六角下る六角町355・354-1合併","lat":35.00688056,"lng":135.75675278,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積153㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"26 － 0632","desc":"新町通に西面し、表屋造風の平面構成のうち表屋部を洋館とする。洋館は直線的で簡明な意匠の立面とし、内部は上下階とも一室である。後方居住部の一階南寄りに土間を通し、北側は中廊下式で南北に居室を配する。昭和初期の京都における近代住宅の潮流を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013826"},{"id":"00013827","register_sub_id":"101","register_pk":"507789","name":"旧寺江家住宅離れ","kana":"きゅうてらえけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区新町通六角下る六角町355・354-1合併","lat":35.0069,"lng":135.75703889,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積28㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"26 － 0633","desc":"敷地東奥、主屋の後方に南北棟で建つ。二階建切妻造桟瓦葺で、西面に庇を付す。外壁は真壁造でガラス戸を建てる。一階は土間の玄関と板間の商品置場からなり、二階は二室を配して従業員休憩所などとした。生業としていた染色業の店舗の業態を伝える附属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013827"},{"id":"00002414","register_sub_id":"101","register_pk":"103404","name":"旧並河靖之邸主屋","kana":"きゅうなみかわやすゆきていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市東山区三条通北裏白川筋東入堀池町384、385、388","lat":35.009876,"lng":135.781372,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積238㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"26 － 0091","desc":"七宝作家並河靖之の自邸。いわゆる表屋造で，表側はせがいの軒に虫籠窓，名栗の駒寄せといった伝統的な京町家の構えをもつ。良材を用い瀟洒な意匠でまとめられるが，内法が高く，庭園に面する縁先は総ガラス戸入りとするなど，新時代の要素がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002414"},{"id":"00012761","register_sub_id":"101","register_pk":"367664","name":"旧松原家住宅主屋","kana":"きゅうまつばらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府木津川市山城町上狛学校７","lat":34.75358583,"lng":135.81661778,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積240㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"26 － 587","desc":"市西部の集落にある農家主屋。南正面の入母屋造桟瓦葺、平屋建で四周に下屋を廻し、下屋上に虫籠窓を穿つ。東に土間、西の前後に各3室を配して中廊下を通し、前列上手に座敷を設ける。伝統形式を踏襲しつつ平面や座敷等の意匠に時代感覚を現す近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012761"},{"id":"00009992","register_sub_id":"101","register_pk":"196139","name":"旧村西家住宅主屋","kana":"きゅうむらにしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区蛸薬師通高倉西入泉正寺町333","lat":35.0062895,"lng":135.76229005,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積135㎡、門及び塀付","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0448","desc":"通り沿いの高塀の奥に建物を配する、いわゆる大塀造町家の外観とする一方で、正面に洋間と茶室を配して奥は中廊下式とし、さらに二階にも洋風の書斎を設けるなど、近代の住宅思潮を取入れた平面形式と意匠をもつ。洋風生活への対応を進めた近代京町家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009992"},{"id":"00009993","register_sub_id":"101","register_pk":"196140","name":"旧村西家住宅土蔵","kana":"きゅうむらにしけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区蛸薬師通高倉西入泉正寺町333","lat":35.00635376,"lng":135.76221594,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0449","desc":"主屋後方に、中庭を挟んで東西棟で建つ。土蔵造二階建、桁行四・六メートル梁間三・九メートル、切妻造本瓦葺で、東面を戸口として下屋を設ける。外壁漆喰塗で鉢巻と水切を廻らして腰は杉皮を張り、上下階南面と二階東面に窓を穿つ。良質な庭景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009993"},{"id":"00012388","register_sub_id":"101","register_pk":"531712","name":"旧森啓次郎邸主屋","kana":"きゅうもりけいじろうていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市山科区日ノ岡夷谷町21-8","lat":35.00332778,"lng":135.79222778,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積92㎡","structure_material":"木造平屋一部2階建","registered":"2018.05.10(平成30.05.10)","register_no":"26-572","desc":"京都九条山の住宅地に建つ。設計･施工は京都あめりか屋。外壁はスタッコ仕上のスパニッシュ風、屋根はフランス瓦葺とする。内部は洋式の起居様式で一貫し、接客空間の居間とサンパーラーには個性的な装飾を多用する。施主の趣味や生活思想を反映した洋風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012388"},{"id":"00007376","register_sub_id":"101","register_pk":"108358","name":"京都工芸繊維大学ＫＩＴ倶楽部（旧舟岡家住宅離れ）","kana":"きょうとこうげいせんいだいがくけーあいてぃーくらぶ（きゅうふなおかけじゅうたくはなれ）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区松ヶ崎鞍馬田町15-1","lat":35.0508049,"lng":135.78191004,"geo_status":"db","era":"昭和4／平成20改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積88㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"26 － 0322","desc":"桁行１２ｍ梁間７．３ｍ規模、切妻造、木造２階建の住宅建築。外壁はモルタル塗とし、矩勾配の屋根にドーマーウィンドウを付ける。内部は暖炉付の応接間や座敷飾りを備える和室などからなる。装飾を抑えた上質なつくりで、ヴォーリズの作風の一端を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007376"},{"id":"00002940","register_sub_id":"101","register_pk":"103930","name":"桐村家住宅主屋","kana":"きりむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府福知山市上小田196","lat":35.32792516,"lng":135.07034436,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積106㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0130","desc":"市北西部，国道９号に接する六十内地区にある。木造二階建，切妻造，桟瓦葺，平入で，東西に長い敷地の中央に建つ。真壁造，腰を簓子下見板張とし，養蚕に使われていた二階の中央部に越屋根を設ける。内外部とも丁寧な造りで，洗練された意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002940"},{"id":"00002942","register_sub_id":"101","register_pk":"103932","name":"桐村家住宅土蔵","kana":"きりむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府福知山市上小田196","lat":35.32776323,"lng":135.07031811,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0132","desc":"敷地南部に位置する。切妻造妻入，外装漆喰塗，桟瓦葺の土蔵で，簡素ながら丁寧に造られた開口部の意匠などを見所とする。屋敷で唯一通りに面した建築物で，街路の歴史的景観の形成に寄与している。主屋，別座敷と共に一般公開し，市民に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002942"},{"id":"00002941","register_sub_id":"101","register_pk":"103931","name":"桐村家住宅別座敷","kana":"きりむらけじゅうたくべつざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府福知山市上小田196","lat":35.32797179,"lng":135.07052737,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積23㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0131","desc":"敷地奥の東南端に位置する。木造２階建，桟瓦葺の入母屋造で，外観は，水切り庇を付けた大壁部分と，広い開口部を設けた真壁部分からなり，２階張出し部の上部にバージーボード風の幕板を付けるなど洋風を加味し，全体として変化のある外観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002941"},{"id":"00002053","register_sub_id":"101","register_pk":"103043","name":"キンシ正宗堀野記念館（旧堀野家本宅）文庫蔵","kana":"きんしまさむねほりのきねんかん（きゅうほりのけほんたく）ぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市中京区堺町通二条上る亀屋町172","lat":35.01407052,"lng":135.762787,"geo_status":"db","era":"文政3","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"26 － 0076","desc":"主屋の西方，井戸の奥に建つ。桁行２間半，梁行２間半規模，南北棟，切妻造，本瓦葺，平入のたちの低い２階建土蔵で，東面に桟瓦葺の庇を差し掛けて戸前をする。２階棟木下の棟札により文政３年８月４日の上棟，「棟梁 三巻善兵衛」が判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002053"},{"id":"00006865","register_sub_id":"101","register_pk":"107847","name":"久保家住宅（旧今尾景年家住宅）主屋","kana":"くぼけじゅうたく（きゅういまおけいねんけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区六角通新町西入西六角町101他","lat":35.00748014,"lng":135.75573501,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積333㎡","structure_material":"木造2階一部平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"26 － 0273","desc":"六角通に南面する敷地の中央部に建つ。主体部は桁行１０間梁間６間規模で、東はもと土間とし、西端に１０畳と１５畳の続き座敷を配し、南には１０畳の応接室を持つ玄関棟を廊下で繋げ、２階に１５畳の画室を設ける。良材を用いた品格ある近代和風住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006865"},{"id":"00006868","register_sub_id":"101","register_pk":"107850","name":"久保家住宅（旧今尾景年家住宅）中門","kana":"くぼけじゅうたく（きゅういまおけいねんけじゅうたく）ちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区六角通新町西入西六角町101他","lat":35.00761004,"lng":135.75567925,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、瓦葺、間口1.3m","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"26 － 0276","desc":"主屋座敷の北方の庭と、土間続きの裏庭とを東西に区切る位置に建つ。間口は１．３ｍ規模の中門で、腕木門形式とし、本柱と腕木、棟木、母屋、垂木などに磨き丸太を用い、冠木には曲材を用いる。屋根は切妻造で、中央部を瓦葺、周囲を銅板葺として瀟洒につくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006868"},{"id":"00006866","register_sub_id":"101","register_pk":"107848","name":"久保家住宅（旧今尾景年家住宅）土蔵","kana":"くぼけじゅうたく（きゅういまおけいねんけじゅうたく）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区六角通新町西入西六角町101他","lat":35.00766209,"lng":135.75564084,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"26 － 0274","desc":"主屋の北方、敷地の北西隅部に位置し、東西棟で建つ。桁行３間半梁間２間半、切妻造本瓦葺の２階建土蔵で、南面に庇を差し掛けて戸口を設ける。外壁は白漆喰塗で、窓には装飾的な持送りに支持された小庇を付け、掛子塗の扉を建て込むなど丁寧なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006866"},{"id":"00006867","register_sub_id":"101","register_pk":"107849","name":"久保家住宅（旧今尾景年家住宅）門及び塀","kana":"くぼけじゅうたく（きゅういまおけいねんけじゅうたく）もんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区六角通新町西入西六角町101他","lat":35.00737813,"lng":135.75572362,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、瓦葺、延長14m","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"26 － 0275","desc":"主屋玄関部の南方、六角通に沿って建つ。木造、真壁造、桟瓦葺の高塀で、腰を竪板張、上部を白漆喰塗とする。東側を間口４．４ｍの門口とし、前後に小庇を差し掛け、通りからやや退いて戸を吊り込み、西側には武者窓を設けるなど、意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006867"},{"id":"00011347","register_sub_id":"101","register_pk":"209184","name":"熊谷家住宅主屋","kana":"くまがいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市下京区室町通五条上る坂東屋町280他","lat":34.99677832,"lng":135.75797589,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造２階建、瓦葺、建築面積186㎡","structure_material":"木造２階建","registered":"2016.11.29(平成28.11.29)","register_no":"26－0511","desc":"東面して建つ呉服商の居宅。間口一二メートルの敷地に建ち、中程に東西廊下を通して北側に座敷等を、南側にダイドコ等を配す。室内に土間を設けず、一・二階とも正面側に洋間を設け、和洋とも上質な意匠を持つ。大塀造風にまとめる、近代的要素の強い住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011347"},{"id":"00011348","register_sub_id":"101","register_pk":"209185","name":"熊谷家住宅門及び塀","kana":"くまがいけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市下京区室町通五条上る坂東屋町280他","lat":34.99676998,"lng":135.7581085,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"門 木造、瓦葺、間口1.4m 塀 木造、瓦葺、総延長25m、供待、玄関戸付","structure_material":"門 木造","registered":"2016.11.29(平成28.11.29)","register_no":"26－0512","desc":"敷地正面から矩折れに両側面を画す。南端に玄関を開き、供待を備え、その奥には勝手口を設けて内向き部分を画する。中央やや南寄りには主屋洋室に合せて出格子窓を設け銅板で庇を葺く。長押下を幅広の竪板張、上部を土壁とし、繊維問屋街の景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011348"},{"id":"00010318","register_sub_id":"101","register_pk":"199091","name":"栗原家住宅主屋","kana":"くりはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市山科区御陵大岩17-2","lat":34.999902,"lng":135.802923,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"コンクリートブロック造3階建、建築面積186㎡","structure_material":"コンクリートブロック造3階建","registered":"2014.12.19(平成26.12.19)","register_no":"26-0464","desc":"中村式鉄筋コンクリートブロック造の三階建住宅。直方体を複合した外観を持ち、正面中央の玄関ポーチと直上の居間を半円形に張出す。内部は階段ホールを中心に、洋間を主とする各室を配する。中村の唱えた構造的合理性と美観性が具現化されたモダニズム住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010318"},{"id":"00010319","register_sub_id":"101","register_pk":"199092","name":"栗原家住宅門及び塀","kana":"くりはらけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市山科区御陵大岩17-2","lat":34.99999834,"lng":135.80284895,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"門柱4基 鉄筋コンクリート造 塀 コンクリートブロック造、総延長36m、潜及び物置付","structure_material":"門柱4基 鉄筋コンクリート造 塀 コンクリートブロック造","registered":"2014.12.19(平成26.12.19)","register_no":"26-0465","desc":"主屋と同じく中村式鉄筋コンクリートブロックを主構造とする塀で、物置を附属する。敷地北西辺を折曲がりに囲み総延長三五メートルを測り、西面中央に正門、北辺東寄りに通用門を開き、門柱を立てる。主屋と一体的な意匠になり、堅牢な趣をみせる門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010319"},{"id":"00015325","register_sub_id":"101","register_pk":"532449","name":"向日庵（旧寿岳家住宅）主屋","kana":"こうじつあん（きゅうじゅがくけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府向日市上植野町浄徳10-1","lat":34.93856389,"lng":135.70514167,"geo_status":"db","era":"昭和8年／昭和62年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"26 - 0686","desc":"阪急西向日駅の南東にある英文学者寿岳文章の住宅主屋。2階建で切妻屋根の勾配緩く、軽快な外観。玄関から中廊下で書庫付書斎へ至り南に和室３室を配す。各室には地窓と欄間を対で配するなど換気に配慮した住環境とし、学者らしく大規模な書庫を備えた主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015325"},{"id":"00015326","register_sub_id":"101","register_pk":"532450","name":"向日庵（旧寿岳家住宅）門及び土留","kana":"こうじつあん（きゅうじゅがくけじゅうたく）もんおよびどどめ","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府向日市上植野町浄徳10-1","lat":34.93861667,"lng":135.70505278,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"門 鉄筋コンクリート造、間口1.7m 土留 石積、総延長38m","structure_material":"門 鉄筋コンクリート造","registered":"2025.03.13(令和7.03.13)","register_no":"26 - 0687","desc":"通りに北面する表門。鉄筋コンクリート造、高さ1・6メートルの門柱はモルタル塗仕上で、隅に緑色タイルを貼ってアクセントとし、西側門柱に照明と郵便受を組み込む。両脇に続く植木用土留は玉石で積み、門とともに昭和戦前開発の郊外住宅地の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015326"},{"id":"00011732","register_sub_id":"101","register_pk":"210748","name":"去木庵（長谷川家住宅離れ）","kana":"こもくあん（はせがわけじゅうたくはなれ）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市南区東九条東札辻町5-1","lat":34.974928,"lng":135.763174,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積65㎡","structure_material":"木造2階一部平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"26-0521","desc":"敷地南東隅に建つ木造二階建で、二階は通り沿いの隅部に高欄付の縁を廻らす。数寄屋を加味した和風意匠を基調とするが、障子や欄間などにガラスを多用し、組子などの細部には様々な幾何学的意匠を取り入れる。設計した画家の独創性がうかがえる離れ建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011732"},{"id":"00015034","register_sub_id":"101","register_pk":"529312","name":"近藤家住宅主屋","kana":"こんどうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府南丹市日吉町中世木中島3","lat":35.15694444,"lng":135.53775,"geo_status":"db","era":"江戸末期／昭和9年増築、平成3年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺一部瓦葺、建築面積199㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"26 - 0676","desc":"天若湖の北の谷間にある農家の主屋。敷地北寄りに南面して建つ入母屋造平入茅葺で、周囲に桟瓦葺下屋を廻し、東に入母屋造桟瓦葺の増築棟を延ばす。内部は西に玄関、東に6室配し、南東室を庭に面した座敷とする。茅葺屋根が地域の歴史的な景観をつくる民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015034"},{"id":"00002642","register_sub_id":"101","register_pk":"103632","name":"近藤家住宅主屋","kana":"こんどうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府城陽市寺田乾出北11","lat":34.854931,"lng":135.770645,"geo_status":"db","era":"18世紀後期","year":1780,"year_source":"estimated","year_min":1761,"year_max":1800,"year_label":"18世紀後期","structure":"木造平屋建、瓦葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"26 － 0098","desc":"幕府領の村役を務めた農家の主屋。通りに向かって北面し，桁行７間，梁間３間半，東半を土間，西半を田字型平面の座敷部とする。つし２階を設け正面に虫籠窓を明け，屋根は登梁形式の小屋組で入母屋造，桟瓦葺とする。南山城で最初期の瓦葺農家の姿を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002642"},{"id":"00002643","register_sub_id":"101","register_pk":"103633","name":"近藤家住宅離れ座敷","kana":"こんどうけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府城陽市寺田乾出北11","lat":34.855022,"lng":135.770523,"geo_status":"db","era":"18世紀後期／大正5移築","year":1780,"year_source":"estimated","year_min":1761,"year_max":1800,"year_label":"18世紀後期","structure":"木造平屋建、瓦葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"26 － 0099","desc":"文化年間に領主を迎えるため鳥羽から移築したと伝え，さらに大正５年に主屋北西の現位置に移された。８畳の主室，次の間，４畳の控えの間からなり，主室に床・違棚・付書院を備え，次の間境に竹ノ節欄間を入れる。面皮の柱・長押を用いた瀟洒な数寄屋風書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002643"},{"id":"00001396","register_sub_id":"101","register_pk":"102386","name":"齋藤家住宅","kana":"さいとうけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市左京区吉田神楽岡町8-158","lat":35.02649376,"lng":135.78810028,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、銅板葺、建築面積90㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"26 － 0047","desc":"大正末期から昭和１７年頃にかけて神楽岡北東傾斜地に８ブロックに分けて，主に京大教官を対象に建設された２８件の借家の内の１件。木造２階建銅板葺の瀟洒な和風の外観を持つ。２階に独立の子供部屋を持つ点に特徴がある。設計者は前田巧。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001396"},{"id":"00005636","register_sub_id":"101","register_pk":"106624","name":"ザイラー家住宅音楽堂","kana":"ざいらーけじゅうたくおんがくどう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府南丹市日吉町上胡麻南2","lat":35.18740483,"lng":135.46977886,"geo_status":"db","era":"天明4／平成元移築","year":1784,"year_source":"db","year_min":1784,"year_max":1784,"year_label":null,"structure":"木造平屋建、茅葺、建築面積192㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"26 － 0223","desc":"主屋の南方，一段高い敷地に北面して建つ。建築面積１９２㎡，南北棟，入母屋造，茅葺，木造平屋建で，玄関及び東面に瓦葺の庇をかける。天明年間の寺院本堂兼庫裏の建物を前身とし，移築後もその規模，形状，柱位置等を踏襲し，特徴を良くとどめており，貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005636"},{"id":"00005635","register_sub_id":"101","register_pk":"106623","name":"ザイラー家住宅主屋","kana":"ざいらーけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府南丹市日吉町上胡麻南2","lat":35.18762831,"lng":135.46977983,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、茅葺、建築面積106㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"26 － 0222","desc":"敷地北方に西面して建つ。建築面積１０６㎡，南北棟，入母屋造，茅葺，木造平屋建で，東面，西面，南面にそれぞれ瓦葺で下屋をかける。棟に鞍木を置く。外壁は漆喰仕上げとし，腰まで竪板張とする。伝統的な農村景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005635"},{"id":"00015033","register_sub_id":"101","register_pk":"529311","name":"酒井家住宅主屋","kana":"さかいけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府亀岡市西別院町犬甘野太歳41","lat":34.96566389,"lng":135.50189444,"geo_status":"db","era":"江戸後期／昭和中期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（鉄板仮葺）一部瓦葺、建築面積165㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"26 - 0675","desc":"亀岡市南西の山間に位置する旧家の主屋。敷地中央に南面して建つ入母屋造平入茅葺（鉄板仮葺）で四周に桟瓦葺下屋を付す。内部は西に土間、東に6室を配し、南東室が床、違棚、付書院を備えた座敷。軸部木太く、南面中央に式台を構えて、格式を備えた主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015033"},{"id":"00001428","register_sub_id":"101","register_pk":"102418","name":"佐々木家住宅","kana":"ささきけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市上京区上立売通大宮一丁目東入下る藤木町783","lat":35.03160648,"lng":135.75035656,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積155㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"26 － 0051","desc":"つし二階建ての中規模な町家で，通り土間に沿って居室２列を配する。屋根は切妻造で，上手１列は棟を一段低くする。二階正面に虫籠窓と格子窓を配し，土間側正面の円形虫籠窓は京都では珍しい。江戸後期の京都町家の姿を伝えるものとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001428"},{"id":"00007378","register_sub_id":"101","register_pk":"108360","name":"佐藤家住宅雑具蔵","kana":"さとうけじゅうたくざつぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府長岡京市長法寺祭ノ神7","lat":34.932758,"lng":135.678497,"geo_status":"db","era":"嘉永年間","year":1851,"year_source":"estimated","year_min":1848,"year_max":1854,"year_label":"嘉永年間","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"26 － 0324","desc":"主屋の北側西寄りに南北棟で建つ土蔵造２階建。桁行９．７ｍ梁間４．０ｍの細長い建物で、切妻造桟瓦葺の置屋根とする。東面の中央やや南寄りに両開戸を吊り、その前に板床を張り、庇を掛ける。内部は一室で、２階天井には細い帯鉄を張っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007378"},{"id":"00007377","register_sub_id":"101","register_pk":"108359","name":"佐藤家住宅主屋","kana":"さとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府長岡京市長法寺祭ノ神7","lat":34.932652,"lng":135.678635,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積196㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"26 － 0323","desc":"敷地の中央に南面して建つ。桁行８間梁間６間半規模のつし２階建。入母屋造桟瓦葺で、四周に庇をまわす。当初は東寄り２間半を土間、西側を３列３行の九間取の床上部とした。座敷飾りや欄間、建具などに格式ある構えを見せる。近代初頭に遡る大型の農家建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007377"},{"id":"00007379","register_sub_id":"101","register_pk":"108361","name":"佐藤家住宅新蔵","kana":"さとうけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府長岡京市長法寺祭ノ神7","lat":34.932838,"lng":135.678467,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積12㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"26 － 0325","desc":"雑具蔵の北に南北棟で建つ土蔵造２階建。桁行４．０ｍ梁間３．０ｍで、切妻造桟瓦葺の置屋根とする。東面中央を戸口とし、正面に奥行１．８ｍの板床を張り、庇を掛ける。外壁は漆喰仕上げで北・西面に竪板を張る。鉢巻など丁寧な仕上げになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007379"},{"id":"00007385","register_sub_id":"101","register_pk":"108367","name":"佐藤家住宅高塀","kana":"さとうけじゅうたくたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府長岡京市長法寺祭ノ神7","lat":34.93280881,"lng":135.67871379,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、延長40m","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"26 － 0331","desc":"敷地東辺の築地塀北端から、北辺の東米蔵までの折曲り延長４０ｍに及ぶ。通り側は切石積石垣上に土台を置く。腰は高く焼杉板を張る高塀で、柱上部で腕木を出し、桟瓦葺屋根を支える。内部は漆喰の大壁仕上げとする。伝統的な集落景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007385"},{"id":"00007384","register_sub_id":"101","register_pk":"108366","name":"佐藤家住宅築地塀","kana":"さとうけじゅうたくついじべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府長岡京市長法寺祭ノ神7","lat":34.93254949,"lng":135.67843521,"geo_status":"db","era":"江戸期","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"土塀、瓦葺、延長68m","structure_material":"土塀","registered":"2008.10.23(平成20.10.23)","register_no":"26 － 0330","desc":"長屋門物置の西端から南辺と西辺を画する延長５７ｍの塀と、長屋門東端から東辺南寄りを画する延長１１ｍからなる。高さは１．５０～１．９ｍで、低い石垣上に築き、頂部に桟瓦を葺く。表面を鏝塗で仕上げ、波模様を施す。落ち着いた佇まいの屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007384"},{"id":"00007382","register_sub_id":"101","register_pk":"108364","name":"佐藤家住宅長屋門","kana":"さとうけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府長岡京市長法寺祭ノ神7","lat":34.932533,"lng":135.678802,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積6.7㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"26 － 0328","desc":"敷地南辺の東端に南面して建つ。敷地形状のためにやや折れ曲がった平面となる。切妻造桟瓦葺。門口と、その東のもと男衆部屋からなり、北面を開放する物置を西面に付設する。門口には両開板戸を吊り、戸口手前の妻側に、踏み越しとする潜りを設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007382"},{"id":"00007380","register_sub_id":"101","register_pk":"108362","name":"佐藤家住宅西米蔵","kana":"さとうけじゅうたくにしこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府長岡京市長法寺祭ノ神7","lat":34.932854,"lng":135.678528,"geo_status":"db","era":"文化4","year":1807,"year_source":"db","year_min":1807,"year_max":1807,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積15㎡","structure_material":"土蔵造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"26 － 0326","desc":"敷地の北辺、新蔵の東に東西棟で建つ。桁行３．９ｍ梁間３．９ｍのほぼ正方形に近い平面をもつ土蔵造平屋建である。切妻造で北流れ桟瓦葺。南流れは本瓦葺とし、桟瓦葺の庇を掛け、重厚な雰囲気を残す。外壁は白漆喰仕上げ、北面通り側に竪板を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007380"},{"id":"00007381","register_sub_id":"101","register_pk":"108363","name":"佐藤家住宅東米蔵","kana":"さとうけじゅうたくひがしこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府長岡京市長法寺祭ノ神7","lat":34.932869,"lng":135.678574,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積15㎡","structure_material":"土蔵造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"26 － 0327","desc":"敷地の北辺、西米蔵の東に接して建つ。桁行５．０ｍ梁間３．０ｍの土蔵造平屋建。切妻造桟瓦葺で、正面に奥行の深い庇を付ける。外壁は漆喰仕上げとし、南面中央に入口を開く。棟を段違いとする東米蔵と西米蔵、妻を見せる新蔵が変化のある屋敷景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007381"},{"id":"00007383","register_sub_id":"101","register_pk":"108365","name":"佐藤家住宅露地門及び庭塀","kana":"さとうけじゅうたくろじもんおよびにわべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府長岡京市長法寺祭ノ神7","lat":34.93254644,"lng":135.67867512,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"門 木造、瓦葺、間口1.2m 塀 木造、瓦葺、延長9.9m","structure_material":"門 木造","registered":"2008.10.23(平成20.10.23)","register_no":"26 － 0329","desc":"主屋土間前方の門庭と、座敷前の庭を区画する。露地門は間口１．２ｍの一間一戸腕木門。一軒疎垂木で、切妻造桟瓦葺とする。吹寄せ桟や襷桟を用いた開戸を吊り、瀟洒な印象を与える。庭塀は延長９．９ｍ、桟瓦葺。門庭側を赤色の土壁とし、腰に下見板を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007383"},{"id":"00004681","register_sub_id":"101","register_pk":"105671","name":"重森三玲邸書院・茶室","kana":"しげもりみれいていしょいん・ちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市左京区吉田上大路町34-23","lat":35.02414368,"lng":135.7822764,"geo_status":"db","era":"江戸末期／昭和28増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"26 － 0192","desc":"平屋建で南の１５畳の書院，北の６畳の裏書院及び茶室からなる。書院は北に床・棚・書院を構え，床の前方１間筋に無目を入れて小壁をつくり，南を棹縁天井，北を格天井とした独特の構成。「撫字庵」と号する増築部の茶室は，作庭家重森三玲の代表作のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004681"},{"id":"00007231","register_sub_id":"101","register_pk":"108213","name":"柴田家住宅主屋","kana":"しばたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市右京区京北鳥居町市無43","lat":35.172398,"lng":135.649948,"geo_status":"db","era":"大正元／平成9改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積171㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0316","desc":"緩い起りの切妻造桟瓦葺で周囲に庇をまわす。東西棟の桁行６間半梁間５間規模で、西側に土間、東に床上部を設ける。床上部は正面側の西寄りから式台玄関、次の間、座敷が並び、座敷東面にトコと書院、神棚を並べる。木部は弁柄塗。質の高い近代農家建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007231"},{"id":"00007234","register_sub_id":"101","register_pk":"108216","name":"柴田家住宅土塀","kana":"しばたけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市右京区京北鳥居町市無43","lat":35.17241453,"lng":135.65010481,"geo_status":"db","era":"大正元頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土塀、瓦葺、延長42m","structure_material":"土塀","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0319","desc":"露地門南柱からコの字型に庭園と敷地東側を画する。総延長４２ｍ。石垣上に築かれた土塀で、壁面は荒壁とし、一部に中塗仕上げが見られる。切妻で桟瓦を葺き、南北の塀を東西の塀より一段高くする。敷地正面の水路にも石積が残され、伝統的な屋敷景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007234"},{"id":"00007232","register_sub_id":"101","register_pk":"108214","name":"柴田家住宅風呂","kana":"しばたけじゅうたくふろ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市右京区京北鳥居町市無43","lat":35.1723714,"lng":135.64978612,"geo_status":"db","era":"大正元頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積7.0㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0317","desc":"主屋の西北に位置する、東西棟の切妻造桟瓦葺。桁行２．８ｍ梁間２．５ｍで、東寄りを脱衣場とし、西側を浴室とする。側まわりは漆喰壁で、腰は浴室まわりを煉瓦壁、他を板張とする。浴室内は腰が染付けタイル貼、上部が板張。浴槽には小タイルを貼る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007232"},{"id":"00007233","register_sub_id":"101","register_pk":"108215","name":"柴田家住宅露地門","kana":"しばたけじゅうたくろじもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市右京区京北鳥居町市無43","lat":35.17232372,"lng":135.65000603,"geo_status":"db","era":"大正元頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、瓦葺、間口1.9m","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0318","desc":"座敷前の庭園を画する門で、式台東柱の南に袖塀を介して建つ。間口１．９ｍの一間薬医門で、緩い起りの切妻造桟瓦葺。柱上に女梁、冠木、男梁を組み、女梁男梁間に斗を入れる。妻は豕叉首組で、一軒疎垂木。全体を弁柄塗とする。男梁鼻先を木鼻風に造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007233"},{"id":"00001429","register_sub_id":"101","register_pk":"102419","name":"島津創業記念資料館南棟","kana":"しまづそうぎょうきねんしりょうかんなんとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区西木屋町通二条下る東入西生州町478-1","lat":35.01282104,"lng":135.77024966,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造2階建、瓦葺、建築面積138㎡","structure_material":"木造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"26 － 0052","desc":"明治期の科学研究の礎を築いた島津源蔵の住宅兼研究所であった建物で，現在は内部を改装して資料館とする。木造二階建，切妻造，桟瓦葺の伝統的な町家の形式を基調とながら，近代的なデザインを取り入れ，二階は土蔵造風にして大きな窓を並べる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001429"},{"id":"00001430","register_sub_id":"101","register_pk":"102420","name":"島津創業記念資料館北棟","kana":"しまづそうぎょうきねんしりょうかんほくとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区西木屋町通二条下る東入西生州町478-1","lat":35.01294386,"lng":135.77024345,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造2階建、瓦葺、建築面積168㎡","structure_material":"木造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"26 － 0053","desc":"島津源蔵の住宅兼研究所として，南棟の北に増築された本二階建ての建物。屋根は片寄棟造とし，南棟よりも棟を高めている。大斗肘木状の柱頭飾り，ステンドグラスを用いた欄間，軽快な吹き寄せ垂木などのデザイン要素を巧みに取り入れた質の高い和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001430"},{"id":"00009048","register_sub_id":"101","register_pk":"162408","name":"下村家住宅戌亥蔵","kana":"しもむらけじゅうたくいぬいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市伏見区醍醐落保町53","lat":34.94916472,"lng":135.81832677,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0390","desc":"敷地北西角に建ち、渡廊下で主屋に接続する。桁行５．９ｍ梁間３．９ｍの土蔵造二階建で、東面に蔵前を付設し、小屋組は登り梁で、置屋根式の桟瓦葺である。外壁は漆喰仕上げで腰高に竪板張とする。旧家の伝統的な屋敷構えをよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009048"},{"id":"00009046","register_sub_id":"101","register_pk":"162406","name":"下村家住宅主屋","kana":"しもむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市伏見区醍醐落保町53","lat":34.94909639,"lng":135.81845762,"geo_status":"db","era":"江戸後期／明治前期増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、茅葺一部瓦葺、建築面積132㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0388","desc":"醍醐道に北面して建つ。建築面積は１３２㎡。東西棟の入母屋造茅葺で、西側に切妻造桟瓦葺の座敷二室を落棟にして張り出す。内部は東側がもと土間で、西側に二列五室を並べ、仏間と次の間にトコなどを備える。醍醐寺門前の歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009046"},{"id":"00009049","register_sub_id":"101","register_pk":"162409","name":"下村家住宅辰巳蔵","kana":"しもむらけじゅうたくたつみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市伏見区醍醐落保町53","lat":34.94899025,"lng":135.81844163,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0391","desc":"敷地南東角に建つもと米蔵。土蔵造二階建で、小屋は和小屋を組み、切妻造本瓦葺である。平面は梁間３．６ｍ、桁行が北側４．７ｍ、南側４ｍとし、敷地形状により台形を呈する。外壁は鉢巻まで竪板張とし、門前町の景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009049"},{"id":"00009047","register_sub_id":"101","register_pk":"162407","name":"下村家住宅離れ","kana":"しもむらけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市伏見区醍醐落保町53","lat":34.94908621,"lng":135.81831804,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積31㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0389","desc":"主屋の西側に接続して建つ。木造二階建、切妻造桟瓦葺、建築面積３１㎡。一階は六畳と三畳台目茶室で、六畳南面に縁を設けて庭を望む。二階は六畳一室で三面に窓を開く開放的な構成とする。上層農家における、幕末に遡る二階建て離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009047"},{"id":"00001079","register_sub_id":"101","register_pk":"102069","name":"順正清水店（旧松風嘉定邸）","kana":"じゅんせいきよみずてん（きゅうしょうふうかていてい）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市東山区清水2-239","lat":34.9956801,"lng":135.78118291,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造３階建塔屋付，瓦葺，建築面積256㎡","structure_material":"木造３階建塔屋付","registered":"1999.02.17(平成11.02.17)","register_no":"26 － 0034","desc":"清水焼の窯元の家で，清水坂のかたわらに建つ。木造３階建，セセッションスタイルの洋館であるが，屋根を幾重にも重ね，鴟尾を載せるなど場所柄を意識した意匠が採り入れられている。設計は武田五一。現在は，料理店として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001079"},{"id":"00004093","register_sub_id":"101","register_pk":"105083","name":"順正南禅寺本店（順正書院）石門","kana":"じゅんせいなんぜんじほんてん（じゅんせいしょいん）いしもん","category":"住宅","subcategory":"その他工作","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市左京区南禅寺草川町60","lat":35.01154206,"lng":135.79012398,"geo_status":"db","era":"天保10","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"石造冠木門","structure_material":"石造冠木門","registered":"1999.06.07(平成11.06.07)","register_no":"26 － 0036","desc":"書院上段の間を中心に展開される前庭の西側の通路境に設けられた切石積の塀に開かれた門。両脇に板状の大きな切石の親柱を立て、頭部に屋根石を置く簡素な造りになる。内開きの扉は新しいが、斬新なデザインになり、庭への導入部を軽快に演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004093"},{"id":"00004092","register_sub_id":"101","register_pk":"105082","name":"順正南禅寺本店（順正書院）書院","kana":"じゅんせいなんぜんじほんてん（じゅんせいしょいん）しょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市左京区南禅寺草川町60","lat":35.01154206,"lng":135.79012398,"geo_status":"db","era":"天保10","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積279㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"26 － 0035","desc":"南禅寺山門の南に位置する書院で、蘭学医新宮涼庭が所司代間部詮勝の勧めで閑静な佇まいの現地に建てたもの。平面は東南に上段の間を置き西側にイロリの間、次の間などを配し、奥に茶室を付設する。改造はあるが、伝統技法になる上質の書院として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004092"},{"id":"00009333","register_sub_id":"101","register_pk":"194126","name":"角屋松の間","kana":"すみやまつのま","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市下京区西新屋敷揚屋町32","lat":34.99238679,"lng":135.74306664,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0406","desc":"主屋西面北寄りに建つ木造平屋建の離れ。建築面積一一二平方メートル、入母屋造桟瓦葺で、鉄板葺庇を廻らす。東の主屋側から一〇畳口の間、一二畳と八畳の次の間を経て二三畳大広間が雁行して連なり、南側に濡縁がつく。内法高が大きい近代趣味の書院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009333"},{"id":"00000593","register_sub_id":"101","register_pk":"101583","name":"聖ヨゼフ修道院・門","kana":"せいよぜふしゅうどういん・もん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市北区北野東紅梅町6-2-1","lat":35.02893083,"lng":135.73286027,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"煉瓦造，両袖壁延べ2.6m附属","structure_material":"煉瓦造","registered":"1998.07.23(平成10.07.23)","register_no":"26 － 0015","desc":"門衛所と一体的に造られる。門柱の台座と笠石に御影石を用い，袖壁頂部の煉瓦を縦に積む。意匠を凝らした門構えではないが，ところどころにハツリ面を見せた煉瓦を挟んで陰影をあたえるなど細やかな心配りが感じとられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000593"},{"id":"00000592","register_sub_id":"101","register_pk":"101582","name":"聖ヨゼフ修道院門の家","kana":"せいよぜふしゅうどういんもんのいえ","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市北区北野東紅梅町6-2-1","lat":35.02900881,"lng":135.73288447,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積39㎡","structure_material":"木造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"26 － 0014","desc":"住友家京都衣笠別邸の跡地に建つ。煉瓦の腰壁とハツリ目をつけた木部が典型的なハーフティンバーの様式をつくりあげている。もと門衛所であるが，小住宅としての価値を充分有している。住友営繕の多久仁輔（工手学校出身）が担当したとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000592"}];
